const diagrams = {
  "1": "<svg viewBox=\"0 0 760 280\" class=\"w-full h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n    <defs>\n      <linearGradient id=\"bioG1\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n        <stop offset=\"0%\" stop-color=\"#059669\"/>\n        <stop offset=\"100%\" stop-color=\"#0d9488\"/>\n      </linearGradient>\n    </defs>\n    <rect width=\"760\" height=\"280\" rx=\"16\" fill=\"#f0fdf4\" class=\"dark:fill-slate-900\"/>\n    <text x=\"380\" y=\"28\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"800\" fill=\"#065f46\">SƠ ĐỒ HỆ SINH THÁI NGHIÊN CỨU &amp; ỨNG DỤNG SINH HỌC HIỆN ĐẠI</text>\n    <!-- Center Core -->\n    <circle cx=\"380\" cy=\"145\" r=\"52\" fill=\"url(#bioG1)\" stroke=\"#a7f3d0\" stroke-width=\"4\"/>\n    <text x=\"380\" y=\"138\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"#ffffff\">SINH HỌC 10</text>\n    <text x=\"380\" y=\"154\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"600\" fill=\"#d1fae5\">Cơ bản &amp; Ứng dụng</text>\n    <!-- 4 Branches -->\n    <line x1=\"328\" y1=\"120\" x2=\"195\" y2=\"80\" stroke=\"#10b981\" stroke-width=\"2.5\" stroke-dasharray=\"4 3\"/>\n    <line x1=\"328\" y1=\"170\" x2=\"195\" y2=\"210\" stroke=\"#10b981\" stroke-width=\"2.5\" stroke-dasharray=\"4 3\"/>\n    <line x1=\"432\" y1=\"120\" x2=\"565\" y2=\"80\" stroke=\"#0d9488\" stroke-width=\"2.5\" stroke-dasharray=\"4 3\"/>\n    <line x1=\"432\" y1=\"170\" x2=\"565\" y2=\"210\" stroke=\"#0d9488\" stroke-width=\"2.5\" stroke-dasharray=\"4 3\"/>\n    <!-- Box 1: Y duoc & Phap y -->\n    <rect x=\"25\" y=\"45\" width=\"175\" height=\"68\" rx=\"12\" fill=\"#ffffff\" stroke=\"#10b981\" stroke-width=\"2\"/>\n    <text x=\"112\" y=\"68\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"#047857\">1. Y – DƯỢC &amp; PHÁP Y</text>\n    <text x=\"112\" y=\"85\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#334155\">Giải trình tự hệ gene, thuốc đích</text>\n    <text x=\"112\" y=\"100\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#059669\" font-weight=\"700\">Dấu vân tay DNA nhận diện</text>\n    <!-- Box 2: Nong lam ngu nghiep -->\n    <rect x=\"25\" y=\"175\" width=\"175\" height=\"68\" rx=\"12\" fill=\"#ffffff\" stroke=\"#10b981\" stroke-width=\"2\"/>\n    <text x=\"112\" y=\"198\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"#047857\">2. NÔNG – LÂM – NGƯ</text>\n    <text x=\"112\" y=\"215\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#334155\">Giống năng suất, chống chịu cao</text>\n    <text x=\"112\" y=\"230\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#059669\" font-weight=\"700\">Nuôi cấy mô &amp; Công nghệ gene</text>\n    <!-- Box 3: Thuc pham & Moi truong -->\n    <rect x=\"560\" y=\"45\" width=\"175\" height=\"68\" rx=\"12\" fill=\"#ffffff\" stroke=\"#0d9488\" stroke-width=\"2\"/>\n    <text x=\"647\" y=\"68\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"#0f766e\">3. THỰC PHẨM &amp; MÔI TRƯỜNG</text>\n    <text x=\"647\" y=\"85\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#334155\">Chế biến lên men, xử lí ô nhiễm</text>\n    <text x=\"647\" y=\"100\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#0d9488\" font-weight=\"700\">Nhiên liệu &amp; Phỏng sinh học</text>\n    <!-- Box 4: Dao duc & Ben vung -->\n    <rect x=\"560\" y=\"175\" width=\"175\" height=\"68\" rx=\"12\" fill=\"#ffffff\" stroke=\"#0d9488\" stroke-width=\"2\"/>\n    <text x=\"647\" y=\"198\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"#0f766e\">4. ĐẠO ĐỨC &amp; BỀN VỮNG</text>\n    <text x=\"647\" y=\"215\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#334155\">Bảo tồn đa dạng, an toàn GMO</text>\n    <text x=\"647\" y=\"230\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#b45309\" font-weight=\"700\">Đạo đức sinh học (Bioethics)</text>\n    <!-- Bottom Bar -->\n    <rect x=\"210\" y=\"238\" width=\"340\" height=\"28\" rx=\"8\" fill=\"#d1fae5\" stroke=\"#34d399\"/>\n    <text x=\"380\" y=\"256\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\" fill=\"#065f46\">Liên ngành: Tin sinh học (AI) • Hoá sinh • Vật lí sinh học • Y sinh</text>\n  </svg>",
  "2": "<svg viewBox=\"0 0 760 270\" class=\"w-full h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n    <rect width=\"760\" height=\"270\" rx=\"16\" fill=\"#f0fdfa\" class=\"dark:fill-slate-900\"/>\n    <text x=\"380\" y=\"28\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"800\" fill=\"#0f766e\">TIẾN TRÌNH NGHIÊN CỨU KHOA HỌC TRONG SINH HỌC (6 BƯỚC &amp; VÒNG PHẢN HỒI)</text>\n    <!-- 6 Steps Boxes -->\n    <g transform=\"translate(18, 52)\">\n      <rect x=\"0\" y=\"0\" width=\"105\" height=\"76\" rx=\"10\" fill=\"#ffffff\" stroke=\"#0d9488\" stroke-width=\"2\"/>\n      <circle cx=\"20\" cy=\"20\" r=\"11\" fill=\"#0d9488\"/><text x=\"20\" y=\"24\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"800\" fill=\"#fff\">1</text>\n      <text x=\"62\" y=\"24\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"800\" fill=\"#0f766e\">QUAN SÁT</text>\n      <text x=\"52\" y=\"45\" text-anchor=\"middle\" font-size=\"9\" fill=\"#334155\">Thu thập dữ liệu</text>\n      <text x=\"52\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#0d9488\" font-weight=\"600\">Định tính / Định lượng</text>\n    </g>\n    <text x=\"131\" y=\"94\" font-size=\"16\" font-weight=\"900\" fill=\"#0d9488\">→</text>\n    <g transform=\"translate(142, 52)\">\n      <rect x=\"0\" y=\"0\" width=\"105\" height=\"76\" rx=\"10\" fill=\"#ffffff\" stroke=\"#0d9488\" stroke-width=\"2\"/>\n      <circle cx=\"20\" cy=\"20\" r=\"11\" fill=\"#0d9488\"/><text x=\"20\" y=\"24\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"800\" fill=\"#fff\">2</text>\n      <text x=\"64\" y=\"24\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"800\" fill=\"#0f766e\">ĐẶT CÂU HỎI</text>\n      <text x=\"52\" y=\"45\" text-anchor=\"middle\" font-size=\"9\" fill=\"#334155\">Nêu vấn đề cần</text>\n      <text x=\"52\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#0d9488\" font-weight=\"600\">giải thích khoa học</text>\n    </g>\n    <text x=\"255\" y=\"94\" font-size=\"16\" font-weight=\"900\" fill=\"#0d9488\">→</text>\n    <g transform=\"translate(266, 52)\">\n      <rect x=\"0\" y=\"0\" width=\"110\" height=\"76\" rx=\"10\" fill=\"#ecfdf5\" stroke=\"#059669\" stroke-width=\"2.5\"/>\n      <circle cx=\"20\" cy=\"20\" r=\"11\" fill=\"#059669\"/><text x=\"20\" y=\"24\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"800\" fill=\"#fff\">3</text>\n      <text x=\"66\" y=\"24\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"800\" fill=\"#065f46\">GIẢ THUYẾT</text>\n      <text x=\"55\" y=\"45\" text-anchor=\"middle\" font-size=\"9\" fill=\"#334155\">Giải thích giả định</text>\n      <text x=\"55\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#059669\" font-weight=\"700\">Kiểm chứng được</text>\n    </g>\n    <text x=\"384\" y=\"94\" font-size=\"16\" font-weight=\"900\" fill=\"#059669\">→</text>\n    <g transform=\"translate(395, 52)\">\n      <rect x=\"0\" y=\"0\" width=\"105\" height=\"76\" rx=\"10\" fill=\"#ffffff\" stroke=\"#0d9488\" stroke-width=\"2\"/>\n      <circle cx=\"20\" cy=\"20\" r=\"11\" fill=\"#0d9488\"/><text x=\"20\" y=\"24\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"800\" fill=\"#fff\">4</text>\n      <text x=\"62\" y=\"24\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"800\" fill=\"#0f766e\">DỰ ĐOÁN</text>\n      <text x=\"52\" y=\"45\" text-anchor=\"middle\" font-size=\"9\" fill=\"#334155\">Suy luận hệ quả</text>\n      <text x=\"52\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#0d9488\" font-weight=\"600\">“Nếu... thì...”</text>\n    </g>\n    <text x=\"508\" y=\"94\" font-size=\"16\" font-weight=\"900\" fill=\"#0d9488\">→</text>\n    <g transform=\"translate(519, 52)\">\n      <rect x=\"0\" y=\"0\" width=\"108\" height=\"76\" rx=\"10\" fill=\"#ffffff\" stroke=\"#0284c7\" stroke-width=\"2\"/>\n      <circle cx=\"20\" cy=\"20\" r=\"11\" fill=\"#0284c7\"/><text x=\"20\" y=\"24\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"800\" fill=\"#fff\">5</text>\n      <text x=\"64\" y=\"24\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"800\" fill=\"#0369a1\">THỰC NGHIỆM</text>\n      <text x=\"54\" y=\"45\" text-anchor=\"middle\" font-size=\"9\" fill=\"#334155\">Lô đối chứng &amp;</text>\n      <text x=\"54\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#0284c7\" font-weight=\"700\">Lô thí nghiệm</text>\n    </g>\n    <text x=\"634\" y=\"94\" font-size=\"16\" font-weight=\"900\" fill=\"#0284c7\">→</text>\n    <g transform=\"translate(644, 52)\">\n      <rect x=\"0\" y=\"0\" width=\"98\" height=\"76\" rx=\"10\" fill=\"#fef3c7\" stroke=\"#d97706\" stroke-width=\"2\"/>\n      <circle cx=\"18\" cy=\"20\" r=\"11\" fill=\"#d97706\"/><text x=\"18\" y=\"24\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"800\" fill=\"#fff\">6</text>\n      <text x=\"58\" y=\"24\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"800\" fill=\"#b45309\">KẾT LUẬN</text>\n      <text x=\"49\" y=\"45\" text-anchor=\"middle\" font-size=\"9\" fill=\"#334155\">Xử lí số liệu</text>\n      <text x=\"49\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#b45309\" font-weight=\"700\">Đúng / Bác bỏ</text>\n    </g>\n    <!-- Feedback Loop -->\n    <path d=\"M 693 130 L 693 175 L 320 175 L 320 132\" fill=\"none\" stroke=\"#e11d48\" stroke-width=\"2\" stroke-dasharray=\"5 3\"/>\n    <polygon points=\"320,130 315,140 325,140\" fill=\"#e11d48\"/>\n    <rect x=\"375\" y=\"162\" width=\"265\" height=\"24\" rx=\"6\" fill=\"#ffe4e6\" stroke=\"#f43f5e\"/>\n    <text x=\"507\" y=\"178\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#be123c\">Nếu không khớp dự đoán → Điều chỉnh / Đề xuất giả thuyết mới</text>\n    <!-- Bottom Variables Bar -->\n    <rect x=\"40\" y=\"205\" width=\"680\" height=\"46\" rx=\"10\" fill=\"#ffffff\" stroke=\"#94a3b8\"/>\n    <text x=\"380\" y=\"224\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"800\" fill=\"#0f172a\">KIỂM SOÁT BIẾN SỐ TRONG THỰC NGHIỆM SINH HỌC</text>\n    <text x=\"380\" y=\"241\" text-anchor=\"middle\" font-size=\"10\" fill=\"#334155\">• Biến độc lập (chủ động thay đổi)   • Biến phụ thuộc (chỉ tiêu đo đạc)   • Biến kiểm soát (giữ cố định giữa lô TN &amp; Đối chứng)</text>\n  </svg>",
  "3": "<svg viewBox=\"0 0 760 275\" class=\"w-full h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n    <rect width=\"760\" height=\"275\" rx=\"16\" fill=\"#f0fdf4\" class=\"dark:fill-slate-900\"/>\n    <text x=\"380\" y=\"26\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"800\" fill=\"#065f46\">THỨ BẬC CÁC CẤP ĐỘ TỔ CHỨC CỦA THẾ GIỚI SỐNG (TỪ THẤP ĐẾN CAO)</text>\n    <!-- Row 1: Sub-cellular to Organism -->\n    <g font-size=\"10\" font-weight=\"700\" text-anchor=\"middle\">\n      <rect x=\"20\" y=\"48\" width=\"84\" height=\"46\" rx=\"8\" fill=\"#e2e8f0\" stroke=\"#64748b\"/>\n      <text x=\"62\" y=\"68\" fill=\"#334155\">1. Phân tử</text><text x=\"62\" y=\"83\" font-size=\"8.5\" fill=\"#64748b\">DNA, Protein</text>\n      <text x=\"113\" y=\"75\" font-size=\"13\" fill=\"#059669\">→</text>\n      <rect x=\"122\" y=\"48\" width=\"84\" height=\"46\" rx=\"8\" fill=\"#e2e8f0\" stroke=\"#64748b\"/>\n      <text x=\"164\" y=\"68\" fill=\"#334155\">2. Bào quan</text><text x=\"164\" y=\"83\" font-size=\"8.5\" fill=\"#64748b\">Ti thể, Lục lạp</text>\n      <text x=\"215\" y=\"75\" font-size=\"13\" fill=\"#059669\">→</text>\n      <rect x=\"224\" y=\"44\" width=\"96\" height=\"54\" rx=\"10\" fill=\"#d1fae5\" stroke=\"#059669\" stroke-width=\"2.5\"/>\n      <text x=\"272\" y=\"65\" fill=\"#065f46\" font-weight=\"800\">3. TẾ BÀO ★</text><text x=\"272\" y=\"82\" font-size=\"8.5\" fill=\"#047857\">Đơn vị cơ bản</text>\n      <text x=\"329\" y=\"75\" font-size=\"13\" fill=\"#059669\">→</text>\n      <rect x=\"338\" y=\"48\" width=\"76\" height=\"46\" rx=\"8\" fill=\"#ffffff\" stroke=\"#10b981\"/>\n      <text x=\"376\" y=\"68\" fill=\"#065f46\">4. Mô</text><text x=\"376\" y=\"83\" font-size=\"8.5\" fill=\"#64748b\">Mô thần kinh</text>\n      <text x=\"423\" y=\"75\" font-size=\"13\" fill=\"#059669\">→</text>\n      <rect x=\"432\" y=\"48\" width=\"84\" height=\"46\" rx=\"8\" fill=\"#ffffff\" stroke=\"#10b981\"/>\n      <text x=\"474\" y=\"68\" fill=\"#065f46\">5. Cơ quan</text><text x=\"474\" y=\"83\" font-size=\"8.5\" fill=\"#64748b\">Tim, Não, Lá</text>\n      <text x=\"525\" y=\"75\" font-size=\"13\" fill=\"#059669\">→</text>\n      <rect x=\"534\" y=\"48\" width=\"92\" height=\"46\" rx=\"8\" fill=\"#ffffff\" stroke=\"#10b981\"/>\n      <text x=\"580\" y=\"68\" fill=\"#065f46\">6. Hệ cơ quan</text><text x=\"580\" y=\"83\" font-size=\"8.5\" fill=\"#64748b\">Hệ tuần hoàn</text>\n      <text x=\"635\" y=\"75\" font-size=\"13\" fill=\"#059669\">→</text>\n      <rect x=\"644\" y=\"44\" width=\"96\" height=\"54\" rx=\"10\" fill=\"#d1fae5\" stroke=\"#059669\" stroke-width=\"2.5\"/>\n      <text x=\"692\" y=\"65\" fill=\"#065f46\" font-weight=\"800\">7. CƠ THỂ ★</text><text x=\"692\" y=\"82\" font-size=\"8.5\" fill=\"#047857\">Cá thể độc lập</text>\n    </g>\n    <!-- Row 2: Supra-organismal Levels -->\n    <g font-size=\"10.5\" font-weight=\"700\" text-anchor=\"middle\">\n      <rect x=\"55\" y=\"122\" width=\"145\" height=\"56\" rx=\"10\" fill=\"#ccfbf1\" stroke=\"#0d9488\" stroke-width=\"2.5\"/>\n      <text x=\"127\" y=\"144\" fill=\"#0f766e\" font-weight=\"800\">8. QUẦN THỂ ★</text>\n      <text x=\"127\" y=\"162\" font-size=\"9\" fill=\"#115e59\">Cá thể cùng loài, sinh sản</text>\n      <text x=\"215\" y=\"154\" font-size=\"15\" fill=\"#0d9488\">→</text>\n      <rect x=\"230\" y=\"122\" width=\"145\" height=\"56\" rx=\"10\" fill=\"#ccfbf1\" stroke=\"#0d9488\" stroke-width=\"2.5\"/>\n      <text x=\"302\" y=\"144\" fill=\"#0f766e\" font-weight=\"800\">9. QUẦN XÃ ★</text>\n      <text x=\"302\" y=\"162\" font-size=\"9\" fill=\"#115e59\">Các quần thể khác loài</text>\n      <text x=\"390\" y=\"154\" font-size=\"15\" fill=\"#0d9488\">→</text>\n      <rect x=\"405\" y=\"122\" width=\"150\" height=\"56\" rx=\"10\" fill=\"#e0f2fe\" stroke=\"#0284c7\" stroke-width=\"2.5\"/>\n      <text x=\"480\" y=\"144\" fill=\"#0369a1\" font-weight=\"800\">10. HỆ SINH THÁI ★</text>\n      <text x=\"480\" y=\"162\" font-size=\"9\" fill=\"#075985\">Quần xã + Sinh cảnh vô sinh</text>\n      <text x=\"570\" y=\"154\" font-size=\"15\" fill=\"#0284c7\">→</text>\n      <rect x=\"585\" y=\"122\" width=\"130\" height=\"56\" rx=\"10\" fill=\"#fef3c7\" stroke=\"#d97706\" stroke-width=\"2.5\"/>\n      <text x=\"650\" y=\"144\" fill=\"#b45309\" font-weight=\"800\">11. SINH QUYỂN</text>\n      <text x=\"650\" y=\"162\" font-size=\"9\" fill=\"#92400e\">Toàn bộ Trái Đất sống</text>\n    </g>\n    <!-- 3 Core Principles -->\n    <rect x=\"30\" y=\"198\" width=\"700\" height=\"58\" rx=\"12\" fill=\"#ffffff\" stroke=\"#10b981\" stroke-width=\"1.5\"/>\n    <text x=\"380\" y=\"218\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"#065f46\">3 ĐẶC ĐIỂM CHUNG CỐT LÕI CỦA CÁC CẤP ĐỘ TỔ CHỨC SỐNG (★ = Cấp độ cơ bản)</text>\n    <text x=\"155\" y=\"240\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#047857\">① Nguyên tắc thứ bậc (Đặc tính nổi trội)</text>\n    <text x=\"395\" y=\"240\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#0f766e\">② Hệ thống mở &amp; Tự điều chỉnh (Nội môi)</text>\n    <text x=\"615\" y=\"240\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#b45309\">③ Liên tục tiến hoá (Thích nghi &amp; Đa dạng)</text>\n  </svg>",
  "4": "<svg viewBox=\"0 0 760 265\" class=\"w-full h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n    <rect width=\"760\" height=\"265\" rx=\"16\" fill=\"#f0f9ff\" class=\"dark:fill-slate-900\"/>\n    <text x=\"380\" y=\"26\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"800\" fill=\"#0369a1\">CẤU TRÚC PHÂN CỰC CỦA PHÂN TỬ NƯỚC (H₂O) &amp; MẠNG LƯỚI LIÊN KẾT HYDROGEN</text>\n    <!-- Left Box: Elements -->\n    <rect x=\"22\" y=\"46\" width=\"215\" height=\"198\" rx=\"12\" fill=\"#ffffff\" stroke=\"#0284c7\" stroke-width=\"2\"/>\n    <text x=\"130\" y=\"68\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"#0369a1\">NGUYÊN TỐ TRONG TẾ BÀO</text>\n    <rect x=\"36\" y=\"80\" width=\"186\" height=\"68\" rx=\"8\" fill=\"#e0f2fe\"/>\n    <text x=\"129\" y=\"98\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"800\" fill=\"#075985\">Đại lượng (≥ 0,01% khối lượng khô)</text>\n    <text x=\"129\" y=\"116\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\" fill=\"#0284c7\">C, H, O, N (96%), P, S, Ca, K, Mg</text>\n    <text x=\"129\" y=\"134\" text-anchor=\"middle\" font-size=\"9\" fill=\"#334155\">Cấu tạo đại phân tử hữu cơ (Khung C)</text>\n    <rect x=\"36\" y=\"158\" width=\"186\" height=\"72\" rx=\"8\" fill=\"#fef3c7\"/>\n    <text x=\"129\" y=\"176\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"800\" fill=\"#92400e\">Vi lượng (&lt; 0,01% khối lượng khô)</text>\n    <text x=\"129\" y=\"194\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\" fill=\"#d97706\">Fe, I, Zn, Cu, Mn, Mo, Co</text>\n    <text x=\"129\" y=\"212\" text-anchor=\"middle\" font-size=\"9\" fill=\"#334155\">Hoạt hoá Enzyme, Hormone, Hemoglobin</text>\n    <!-- Center: H2O Polarity & H-bond -->\n    <rect x=\"252\" y=\"46\" width=\"265\" height=\"198\" rx=\"12\" fill=\"#ffffff\" stroke=\"#0284c7\" stroke-width=\"2\"/>\n    <text x=\"384\" y=\"68\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"#0369a1\">TÍNH PHÂN CỰC &amp; LIÊN KẾT HYDROGEN</text>\n    <!-- Central H2O -->\n    <line x1=\"350\" y1=\"135\" x2=\"318\" y2=\"168\" stroke=\"#334155\" stroke-width=\"5\"/>\n    <line x1=\"350\" y1=\"135\" x2=\"382\" y2=\"168\" stroke=\"#334155\" stroke-width=\"5\"/>\n    <circle cx=\"350\" cy=\"130\" r=\"24\" fill=\"#ef4444\"/>\n    <text x=\"350\" y=\"134\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#fff\">O (δ⁻)</text>\n    <circle cx=\"315\" cy=\"172\" r=\"15\" fill=\"#3b82f6\"/>\n    <text x=\"315\" y=\"176\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"800\" fill=\"#fff\">H(δ⁺)</text>\n    <circle cx=\"385\" cy=\"172\" r=\"15\" fill=\"#3b82f6\"/>\n    <text x=\"385\" y=\"176\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"800\" fill=\"#fff\">H(δ⁺)</text>\n    <!-- Neighbor H2O connected by H-bond -->\n    <line x1=\"385\" y1=\"172\" x2=\"445\" y2=\"145\" stroke=\"#0284c7\" stroke-width=\"2.5\" stroke-dasharray=\"4 3\"/>\n    <circle cx=\"462\" cy=\"138\" r=\"20\" fill=\"#ef4444\"/>\n    <text x=\"462\" y=\"142\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"#fff\">O (δ⁻)</text>\n    <circle cx=\"488\" cy=\"168\" r=\"12\" fill=\"#3b82f6\"/><text x=\"488\" y=\"172\" text-anchor=\"middle\" font-size=\"9\" fill=\"#fff\">H</text>\n    <circle cx=\"448\" cy=\"175\" r=\"12\" fill=\"#3b82f6\"/><text x=\"448\" y=\"179\" text-anchor=\"middle\" font-size=\"9\" fill=\"#fff\">H</text>\n    <text x=\"384\" y=\"212\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#0369a1\">––– Liên kết cộng hoá trị phân cực (104,5°)</text>\n    <text x=\"384\" y=\"228\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#e11d48\">- - - Liên kết Hydrogen giữa các phân tử H₂O</text>\n    <!-- Right Box: Roles of Water -->\n    <rect x=\"532\" y=\"46\" width=\"206\" height=\"198\" rx=\"12\" fill=\"#ffffff\" stroke=\"#0d9488\" stroke-width=\"2\"/>\n    <text x=\"635\" y=\"68\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"#0f766e\">VAI TRÒ SINH HỌC CỦA NƯỚC</text>\n    <text x=\"546\" y=\"96\" font-size=\"10\" fill=\"#334155\">💧 <tspan font-weight=\"700\" fill=\"#0f766e\">Dung môi:</tspan> Hoà tan ion &amp; chất phân cực</text>\n    <text x=\"546\" y=\"124\" font-size=\"10\" fill=\"#334155\">⚗️ <tspan font-weight=\"700\" fill=\"#0f766e\">Phản ứng:</tspan> Nguyên liệu thuỷ phân, quang hợp</text>\n    <text x=\"546\" y=\"152\" font-size=\"10\" fill=\"#334155\">🌡️ <tspan font-weight=\"700\" fill=\"#0f766e\">Điều hoà nhiệt:</tspan> Nhiệt dung riêng cao</text>\n    <text x=\"546\" y=\"180\" font-size=\"10\" fill=\"#334155\">🌱 <tspan font-weight=\"700\" fill=\"#0f766e\">Cấu trúc:</tspan> Duy trì sức trương tế bào</text>\n    <text x=\"546\" y=\"208\" font-size=\"10\" fill=\"#334155\">🚚 <tspan font-weight=\"700\" fill=\"#0f766e\">Vận chuyển:</tspan> Máu, nhựa mạch gỗ/rây</text>\n  </svg>",
  "5": "<svg viewBox=\"0 0 760 275\" class=\"w-full h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n    <rect width=\"760\" height=\"275\" rx=\"16\" fill=\"#f8fafc\" class=\"dark:fill-slate-900\"/>\n    <text x=\"380\" y=\"26\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"800\" fill=\"#0f766e\">BỐN NHÓM ĐẠI PHÂN TỬ SINH HỌC CỐT LÕI TRONG TẾ BÀO</text>\n    <!-- 1. Carbohydrate -->\n    <rect x=\"16\" y=\"45\" width=\"172\" height=\"212\" rx=\"12\" fill=\"#ffffff\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n    <rect x=\"16\" y=\"45\" width=\"172\" height=\"32\" rx=\"10\" fill=\"#fef3c7\"/>\n    <text x=\"102\" y=\"65\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"#b45309\">1. CARBOHYDRATE</text>\n    <!-- Hexose rings -->\n    <polygon points=\"52,102 66,94 80,102 80,118 66,126 52,118\" fill=\"#fde68a\" stroke=\"#d97706\" stroke-width=\"2\"/>\n    <line x1=\"80\" y1=\"110\" x2=\"96\" y2=\"110\" stroke=\"#d97706\" stroke-width=\"2.5\"/>\n    <polygon points=\"96,102 110,94 124,102 124,118 110,126 96,118\" fill=\"#fde68a\" stroke=\"#d97706\" stroke-width=\"2\"/>\n    <line x1=\"124\" y1=\"110\" x2=\"140\" y2=\"110\" stroke=\"#d97706\" stroke-width=\"2.5\"/>\n    <polygon points=\"140,102 154,94 168,102 168,118 154,126 140,118\" fill=\"#fde68a\" stroke=\"#d97706\" stroke-width=\"2\"/>\n    <text x=\"102\" y=\"146\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#b45309\">Liên kết Glycosidic</text>\n    <text x=\"102\" y=\"168\" text-anchor=\"middle\" font-size=\"9\" fill=\"#334155\">• Đơn: Glucose, Fructose</text>\n    <text x=\"102\" y=\"186\" text-anchor=\"middle\" font-size=\"9\" fill=\"#334155\">• Đôi: Sucrose, Lactose</text>\n    <text x=\"102\" y=\"204\" text-anchor=\"middle\" font-size=\"9\" fill=\"#334155\">• Đa: Tinh bột, Glycogen,</text>\n    <text x=\"102\" y=\"220\" text-anchor=\"middle\" font-size=\"9\" fill=\"#047857\" font-weight=\"700\">Cellulose, Chitin (Cấu trúc)</text>\n    <text x=\"102\" y=\"242\" text-anchor=\"middle\" font-size=\"9\" fill=\"#b45309\" font-weight=\"700\">→ Năng lượng &amp; Cấu trúc</text>\n\n    <!-- 2. Lipid -->\n    <rect x=\"202\" y=\"45\" width=\"172\" height=\"212\" rx=\"12\" fill=\"#ffffff\" stroke=\"#eab308\" stroke-width=\"2\"/>\n    <rect x=\"202\" y=\"45\" width=\"172\" height=\"32\" rx=\"10\" fill=\"#fef9c3\"/>\n    <text x=\"288\" y=\"65\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"#a16207\">2. LIPID (KỊ NƯỚC)</text>\n    <!-- Phospholipid bilayer icon -->\n    <circle cx=\"255\" cy=\"96\" r=\"8\" fill=\"#0284c7\"/><line x1=\"252\" y1=\"104\" x2=\"250\" y2=\"124\" stroke=\"#ca8a04\" stroke-width=\"2\"/><line x1=\"258\" y1=\"104\" x2=\"262\" y2=\"122\" stroke=\"#ca8a04\" stroke-width=\"2\"/>\n    <circle cx=\"278\" cy=\"96\" r=\"8\" fill=\"#0284c7\"/><line x1=\"275\" y1=\"104\" x2=\"275\" y2=\"124\" stroke=\"#ca8a04\" stroke-width=\"2\"/><line x1=\"281\" y1=\"104\" x2=\"283\" y2=\"124\" stroke=\"#ca8a04\" stroke-width=\"2\"/>\n    <circle cx=\"301\" cy=\"96\" r=\"8\" fill=\"#0284c7\"/><line x1=\"298\" y1=\"104\" x2=\"298\" y2=\"124\" stroke=\"#ca8a04\" stroke-width=\"2\"/><line x1=\"304\" y1=\"104\" x2=\"306\" y2=\"124\" stroke=\"#ca8a04\" stroke-width=\"2\"/>\n    <circle cx=\"324\" cy=\"96\" r=\"8\" fill=\"#0284c7\"/><line x1=\"321\" y1=\"104\" x2=\"321\" y2=\"124\" stroke=\"#ca8a04\" stroke-width=\"2\"/><line x1=\"327\" y1=\"104\" x2=\"329\" y2=\"124\" stroke=\"#ca8a04\" stroke-width=\"2\"/>\n    <text x=\"288\" y=\"146\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#0369a1\">Đầu ưa nước / Đuôi kị nước</text>\n    <text x=\"288\" y=\"168\" text-anchor=\"middle\" font-size=\"9\" fill=\"#334155\">• Mỡ (no) / Dầu (không no)</text>\n    <text x=\"288\" y=\"186\" text-anchor=\"middle\" font-size=\"9\" fill=\"#334155\">• Phospholipid: Màng kép</text>\n    <text x=\"288\" y=\"204\" text-anchor=\"middle\" font-size=\"9\" fill=\"#334155\">• Steroid: Cholesterol,</text>\n    <text x=\"288\" y=\"220\" text-anchor=\"middle\" font-size=\"9\" fill=\"#047857\" font-weight=\"700\">Hormone, Vitamin A,D,E,K</text>\n    <text x=\"288\" y=\"242\" text-anchor=\"middle\" font-size=\"9\" fill=\"#a16207\" font-weight=\"700\">→ Dự trữ &amp; Màng tế bào</text>\n\n    <!-- 3. Protein -->\n    <rect x=\"388\" y=\"45\" width=\"172\" height=\"212\" rx=\"12\" fill=\"#ffffff\" stroke=\"#10b981\" stroke-width=\"2\"/>\n    <rect x=\"388\" y=\"45\" width=\"172\" height=\"32\" rx=\"10\" fill=\"#d1fae5\"/>\n    <text x=\"474\" y=\"65\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"#065f46\">3. PROTEIN (4 BẬC)</text>\n    <path d=\"M 418 112 Q 435 88, 452 112 T 486 112 T 520 112\" fill=\"none\" stroke=\"#059669\" stroke-width=\"3.5\"/>\n    <circle cx=\"422\" cy=\"110\" r=\"5\" fill=\"#10b981\"/><circle cx=\"452\" cy=\"112\" r=\"5\" fill=\"#10b981\"/><circle cx=\"486\" cy=\"112\" r=\"5\" fill=\"#10b981\"/><circle cx=\"518\" cy=\"112\" r=\"5\" fill=\"#10b981\"/>\n    <text x=\"474\" y=\"146\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#065f46\">20 Amino acid (LK Peptide)</text>\n    <text x=\"474\" y=\"168\" text-anchor=\"middle\" font-size=\"9\" fill=\"#334155\">• Bậc 1: Trình tự amino acid</text>\n    <text x=\"474\" y=\"186\" text-anchor=\"middle\" font-size=\"9\" fill=\"#334155\">• Bậc 2: Xoắn α / Gấp nếp β</text>\n    <text x=\"474\" y=\"204\" text-anchor=\"middle\" font-size=\"9\" fill=\"#334155\">• Bậc 3 &amp; 4: Cấu hình 3D</text>\n    <text x=\"474\" y=\"220\" text-anchor=\"middle\" font-size=\"9\" fill=\"#e11d48\" font-weight=\"700\">Nhiệt/pH cao → Biến tính</text>\n    <text x=\"474\" y=\"242\" text-anchor=\"middle\" font-size=\"9\" fill=\"#065f46\" font-weight=\"700\">→ Enzyme, Kháng thể, Kênh</text>\n\n    <!-- 4. Nucleic Acid -->\n    <rect x=\"574\" y=\"45\" width=\"172\" height=\"212\" rx=\"12\" fill=\"#ffffff\" stroke=\"#6366f1\" stroke-width=\"2\"/>\n    <rect x=\"574\" y=\"45\" width=\"172\" height=\"32\" rx=\"10\" fill=\"#e0e7ff\"/>\n    <text x=\"660\" y=\"65\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"#4338ca\">4. NUCLEIC ACID</text>\n    <path d=\"M 615 94 C 635 125, 665 94, 685 125 C 695 132, 705 100, 712 96\" fill=\"none\" stroke=\"#4f46e5\" stroke-width=\"3\"/>\n    <path d=\"M 615 125 C 635 94, 665 125, 685 94 C 695 88, 705 120, 712 124\" fill=\"none\" stroke=\"#06b6d4\" stroke-width=\"3\"/>\n    <text x=\"660\" y=\"146\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#4338ca\">Đơn phân: Nucleotide</text>\n    <text x=\"660\" y=\"168\" text-anchor=\"middle\" font-size=\"9\" fill=\"#334155\">• DNA: Xoắn kép 2 mạch</text>\n    <text x=\"660\" y=\"186\" text-anchor=\"middle\" font-size=\"9\" fill=\"#4338ca\" font-weight=\"700\">NTBS: A=T (2H), G≡C (3H)</text>\n    <text x=\"660\" y=\"204\" text-anchor=\"middle\" font-size=\"9\" fill=\"#334155\">• RNA: 1 mạch (A, U, G, C)</text>\n    <text x=\"660\" y=\"220\" text-anchor=\"middle\" font-size=\"9\" fill=\"#0d9488\" font-weight=\"700\">mRNA, tRNA, rRNA</text>\n    <text x=\"660\" y=\"242\" text-anchor=\"middle\" font-size=\"9\" fill=\"#4338ca\" font-weight=\"700\">→ Lưu giữ &amp; Truyền thông tin</text>\n  </svg>",
  "6": "<svg viewBox=\"0 0 760 260\" class=\"w-full h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n    <rect width=\"760\" height=\"260\" rx=\"16\" fill=\"#f0fdf4\" class=\"dark:fill-slate-900\"/>\n    <text x=\"380\" y=\"26\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"800\" fill=\"#065f46\">THỰC HÀNH ĐỊNH TÍNH: 4 PHẢN ỨNG MÀU NHẬN BIẾT ĐẠI PHÂN TỬ SINH HỌC</text>\n    <!-- Tube 1: Tinh bot -->\n    <g transform=\"translate(28, 46)\">\n      <rect x=\"0\" y=\"0\" width=\"162\" height=\"192\" rx=\"12\" fill=\"#ffffff\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n      <text x=\"81\" y=\"22\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"#1d4ed8\">1. NHẬN BIẾT TINH BỘT</text>\n      <rect x=\"64\" y=\"38\" width=\"34\" height=\"82\" rx=\"15\" fill=\"#e2e8f0\" stroke=\"#475569\" stroke-width=\"2\"/>\n      <path d=\"M 66 72 L 96 72 L 96 105 A 15 15 0 0 1 66 105 Z\" fill=\"#1e3a8a\"/>\n      <text x=\"81\" y=\"140\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#334155\">Thuốc thử: Lugol (Iodine)</text>\n      <text x=\"81\" y=\"158\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"800\" fill=\"#1e3a8a\">Màu XANH TÍM / ĐEN</text>\n      <text x=\"81\" y=\"176\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#64748b\">Iodine cài vào vòng xoắn amylose</text>\n    </g>\n    <!-- Tube 2: Duong khu -->\n    <g transform=\"translate(212, 46)\">\n      <rect x=\"0\" y=\"0\" width=\"162\" height=\"192\" rx=\"12\" fill=\"#ffffff\" stroke=\"#ea580c\" stroke-width=\"2\"/>\n      <text x=\"81\" y=\"22\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"#c2410c\">2. ĐƯỜNG KHỬ (GLUCOSE)</text>\n      <rect x=\"64\" y=\"38\" width=\"34\" height=\"82\" rx=\"15\" fill=\"#e2e8f0\" stroke=\"#475569\" stroke-width=\"2\"/>\n      <path d=\"M 66 72 L 96 72 L 96 105 A 15 15 0 0 1 66 105 Z\" fill=\"#dc2626\"/>\n      <text x=\"81\" y=\"140\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#334155\">Benedict + Đun cách thuỷ</text>\n      <text x=\"81\" y=\"158\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"800\" fill=\"#dc2626\">TỦA ĐỎ GẠCH (Cu₂O↓)</text>\n      <text x=\"81\" y=\"176\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#64748b\">Khử Cu²⁺ (xanh lam) → Cu₂O</text>\n    </g>\n    <!-- Tube 3: Protein -->\n    <g transform=\"translate(396, 46)\">\n      <rect x=\"0\" y=\"0\" width=\"162\" height=\"192\" rx=\"12\" fill=\"#ffffff\" stroke=\"#9333ea\" stroke-width=\"2\"/>\n      <text x=\"81\" y=\"22\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"#7e22ce\">3. NHẬN BIẾT PROTEIN</text>\n      <rect x=\"64\" y=\"38\" width=\"34\" height=\"82\" rx=\"15\" fill=\"#e2e8f0\" stroke=\"#475569\" stroke-width=\"2\"/>\n      <path d=\"M 66 72 L 96 72 L 96 105 A 15 15 0 0 1 66 105 Z\" fill=\"#9333ea\"/>\n      <text x=\"81\" y=\"140\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#334155\">Biuret (NaOH + CuSO₄)</text>\n      <text x=\"81\" y=\"158\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"800\" fill=\"#7e22ce\">Màu TÍM ĐẶC TRƯNG</text>\n      <text x=\"81\" y=\"176\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#64748b\">Phức Cu²⁺ với liên kết peptide</text>\n    </g>\n    <!-- Tube 4: Lipid -->\n    <g transform=\"translate(580, 46)\">\n      <rect x=\"0\" y=\"0\" width=\"154\" height=\"192\" rx=\"12\" fill=\"#ffffff\" stroke=\"#0d9488\" stroke-width=\"2\"/>\n      <text x=\"77\" y=\"22\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"#0f766e\">4. NHẬN BIẾT LIPID</text>\n      <rect x=\"60\" y=\"38\" width=\"34\" height=\"82\" rx=\"15\" fill=\"#e2e8f0\" stroke=\"#475569\" stroke-width=\"2\"/>\n      <path d=\"M 62 72 L 92 72 L 92 105 A 15 15 0 0 1 62 105 Z\" fill=\"#cbd5e1\"/>\n      <circle cx=\"72\" cy=\"85\" r=\"3\" fill=\"#fff\"/><circle cx=\"82\" cy=\"92\" r=\"3.5\" fill=\"#fff\"/><circle cx=\"75\" cy=\"98\" r=\"2.5\" fill=\"#fff\"/>\n      <text x=\"77\" y=\"140\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#334155\">Hoà Ethanol + Thêm nước</text>\n      <text x=\"77\" y=\"158\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"800\" fill=\"#0f766e\">NHŨ TƯƠNG TRẮNG ĐỤC</text>\n      <text x=\"77\" y=\"176\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#64748b\">Không tan trong nước, tạo nhũ</text>\n    </g>\n  </svg>",
  "7": "<svg viewBox=\"0 0 760 270\" class=\"w-full h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n    <rect width=\"760\" height=\"270\" rx=\"16\" fill=\"#f0fdf4\" class=\"dark:fill-slate-900\"/>\n    <text x=\"380\" y=\"26\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"800\" fill=\"#065f46\">SƠ ĐỒ CẤU TRÚC TẾ BÀO NHÂN SƠ (VI KHUẨN ĐIỂN HÌNH)</text>\n    <!-- Capsule (Vo nhay) -->\n    <rect x=\"175\" y=\"68\" width=\"320\" height=\"136\" rx=\"68\" fill=\"#a7f3d0\" stroke=\"#059669\" stroke-width=\"3\"/>\n    <!-- Cell Wall (Thanh peptidoglycan) -->\n    <rect x=\"187\" y=\"80\" width=\"296\" height=\"112\" rx=\"56\" fill=\"#fde68a\" stroke=\"#d97706\" stroke-width=\"2.5\"/>\n    <!-- Plasma Membrane (Mang sinh chat) -->\n    <rect x=\"198\" y=\"91\" width=\"274\" height=\"90\" rx=\"45\" fill=\"#ecfdf5\" stroke=\"#0284c7\" stroke-width=\"2\"/>\n    <!-- Nucleoid (Vung nhan DNA vong) -->\n    <path d=\"M 255 135 C 275 105, 315 165, 345 125 C 375 95, 390 165, 340 150 C 300 135, 270 165, 255 135 Z\" fill=\"none\" stroke=\"#dc2626\" stroke-width=\"3\"/>\n    <!-- Plasmid -->\n    <circle cx=\"422\" cy=\"136\" r=\"16\" fill=\"none\" stroke=\"#7c3aed\" stroke-width=\"3\"/>\n    <!-- Ribosomes 70S -->\n    <circle cx=\"230\" cy=\"120\" r=\"3.5\" fill=\"#0369a1\"/><circle cx=\"242\" cy=\"152\" r=\"3.5\" fill=\"#0369a1\"/><circle cx=\"385\" cy=\"112\" r=\"3.5\" fill=\"#0369a1\"/><circle cx=\"395\" cy=\"158\" r=\"3.5\" fill=\"#0369a1\"/><circle cx=\"445\" cy=\"122\" r=\"3.5\" fill=\"#0369a1\"/>\n    <!-- Flagellum (Roi) -->\n    <path d=\"M 495 136 Q 555 95, 605 138 T 715 128\" fill=\"none\" stroke=\"#047857\" stroke-width=\"4\"/>\n    <!-- Pili (Long bam) -->\n    <line x1=\"220\" y1=\"68\" x2=\"210\" y2=\"50\" stroke=\"#059669\" stroke-width=\"2\"/><line x1=\"270\" y1=\"68\" x2=\"268\" y2=\"48\" stroke=\"#059669\" stroke-width=\"2\"/><line x1=\"330\" y1=\"68\" x2=\"332\" y2=\"48\" stroke=\"#059669\" stroke-width=\"2\"/><line x1=\"390\" y1=\"68\" x2=\"398\" y2=\"48\" stroke=\"#059669\" stroke-width=\"2\"/>\n    <line x1=\"230\" y1=\"204\" x2=\"222\" y2=\"222\" stroke=\"#059669\" stroke-width=\"2\"/><line x1=\"310\" y1=\"204\" x2=\"310\" y2=\"224\" stroke=\"#059669\" stroke-width=\"2\"/><line x1=\"380\" y1=\"204\" x2=\"386\" y2=\"224\" stroke=\"#059669\" stroke-width=\"2\"/>\n    <!-- Labels -->\n    <text x=\"90\" y=\"75\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"800\" fill=\"#047857\">1. Vỏ nhầy (Bảo vệ/Bám)</text>\n    <line x1=\"152\" y1=\"72\" x2=\"182\" y2=\"82\" stroke=\"#047857\" stroke-width=\"1.5\"/>\n    <text x=\"88\" y=\"112\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"800\" fill=\"#b45309\">2. Thành Peptidoglycan</text>\n    <line x1=\"150\" y1=\"110\" x2=\"188\" y2=\"110\" stroke=\"#b45309\" stroke-width=\"1.5\"/>\n    <text x=\"88\" y=\"148\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"800\" fill=\"#0369a1\">3. Màng sinh chất</text>\n    <line x1=\"142\" y1=\"145\" x2=\"198\" y2=\"140\" stroke=\"#0369a1\" stroke-width=\"1.5\"/>\n    <text x=\"88\" y=\"185\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"800\" fill=\"#1e40af\">4. Ribosome 70S (Dịch mã)</text>\n    <line x1=\"156\" y1=\"182\" x2=\"238\" y2=\"154\" stroke=\"#1e40af\" stroke-width=\"1.5\"/>\n    <text x=\"315\" y=\"246\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"800\" fill=\"#dc2626\">5. Vùng nhân (DNA vòng kép, không màng nhân)</text>\n    <line x1=\"315\" y1=\"232\" x2=\"315\" y2=\"155\" stroke=\"#dc2626\" stroke-width=\"1.5\"/>\n    <text x=\"530\" y=\"232\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"800\" fill=\"#7c3aed\">6. Plasmid (DNA vòng nhỏ)</text>\n    <line x1=\"485\" y1=\"220\" x2=\"432\" y2=\"150\" stroke=\"#7c3aed\" stroke-width=\"1.5\"/>\n    <text x=\"635\" y=\"92\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"800\" fill=\"#065f46\">7. Roi / Tiên mao (Di chuyển)</text>\n    <text x=\"455\" y=\"45\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"800\" fill=\"#059669\">8. Lông / Nhung mao (Bám &amp; Tiếp hợp)</text>\n  </svg>",
  "8": "<svg viewBox=\"0 0 760 280\" class=\"w-full h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n    <rect width=\"760\" height=\"280\" rx=\"16\" fill=\"#f0fdfa\" class=\"dark:fill-slate-900\"/>\n    <text x=\"380\" y=\"26\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"800\" fill=\"#0f766e\">TẾ BÀO NHÂN THỰC: HỆ THỐNG NỘI MÀNG &amp; BÀO QUAN CHUYỂN HOÁ NĂNG LƯỢNG</text>\n    <!-- Pathway Box Top: Endomembrane system -->\n    <rect x=\"20\" y=\"44\" width=\"720\" height=\"102\" rx=\"12\" fill=\"#ffffff\" stroke=\"#0d9488\" stroke-width=\"2\"/>\n    <text x=\"380\" y=\"64\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"#0f766e\">CON ĐƯỜNG TỔNG HỢP &amp; VẬN CHUYỂN PROTEIN TIẾT (HỆ THỐNG NỘI MÀNG)</text>\n    <g font-size=\"9.5\" font-weight=\"700\" text-anchor=\"middle\">\n      <rect x=\"35\" y=\"76\" width=\"110\" height=\"54\" rx=\"8\" fill=\"#ede9fe\" stroke=\"#7c3aed\" stroke-width=\"1.5\"/>\n      <text x=\"90\" y=\"96\" fill=\"#5b21b6\">1. NHÂN TẾ BÀO</text><text x=\"90\" y=\"114\" font-size=\"8.5\" fill=\"#4c1d95\">DNA → Phiên mã mRNA</text>\n      <text x=\"156\" y=\"106\" font-size=\"14\" fill=\"#0d9488\">→</text>\n      <rect x=\"168\" y=\"76\" width=\"132\" height=\"54\" rx=\"8\" fill=\"#e0f2fe\" stroke=\"#0284c7\" stroke-width=\"1.5\"/>\n      <text x=\"234\" y=\"96\" fill=\"#0369a1\">2. LƯỚI NỘI CHẤT HẠT</text><text x=\"234\" y=\"114\" font-size=\"8.5\" fill=\"#075985\">Ribosome tổng hợp/gấp cuộn</text>\n      <text x=\"311\" y=\"106\" font-size=\"14\" fill=\"#0d9488\">→</text>\n      <rect x=\"322\" y=\"76\" width=\"98\" height=\"54\" rx=\"8\" fill=\"#fef3c7\" stroke=\"#d97706\" stroke-width=\"1.5\"/>\n      <text x=\"371\" y=\"96\" fill=\"#b45309\">3. TÚI VẬN CHUYỂN</text><text x=\"371\" y=\"114\" font-size=\"8.5\" fill=\"#92400e\">Đưa đến bộ máy Golgi</text>\n      <text x=\"431\" y=\"106\" font-size=\"14\" fill=\"#0d9488\">→</text>\n      <rect x=\"442\" y=\"76\" width=\"130\" height=\"54\" rx=\"8\" fill=\"#fce7f3\" stroke=\"#db2777\" stroke-width=\"1.5\"/>\n      <text x=\"507\" y=\"96\" fill=\"#be185d\">4. BỘ MÁY GOLGI</text><text x=\"507\" y=\"114\" font-size=\"8.5\" fill=\"#9d174d\">Hoàn thiện, gắn nhãn, đóng gói</text>\n      <text x=\"583\" y=\"106\" font-size=\"14\" fill=\"#0d9488\">→</text>\n      <rect x=\"595\" y=\"76\" width=\"130\" height=\"54\" rx=\"8\" fill=\"#d1fae5\" stroke=\"#059669\" stroke-width=\"1.5\"/>\n      <text x=\"660\" y=\"96\" fill=\"#065f46\">5. TÚI TIẾT / MÀNG</text><text x=\"660\" y=\"114\" font-size=\"8.5\" fill=\"#047857\">Xuất bào hoặc tạo Lysosome</text>\n    </g>\n    <!-- Bottom Row: Mitochondria vs Chloroplast vs Plant/Animal diff -->\n    <rect x=\"20\" y=\"160\" width=\"230\" height=\"104\" rx=\"12\" fill=\"#ffffff\" stroke=\"#e11d48\" stroke-width=\"2\"/>\n    <text x=\"135\" y=\"180\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"#be123c\">TI THỂ (HÔ HẤP TẾ BÀO)</text>\n    <ellipse cx=\"72\" cy=\"218\" rx=\"36\" ry=\"22\" fill=\"#ffe4e6\" stroke=\"#e11d48\" stroke-width=\"2\"/>\n    <path d=\"M 45 218 Q 55 202, 62 218 T 78 218 T 96 218\" fill=\"none\" stroke=\"#be123c\" stroke-width=\"2\"/>\n    <text x=\"168\" y=\"205\" text-anchor=\"middle\" font-size=\"9\" fill=\"#334155\">• Màng kép, trong gấp mào</text>\n    <text x=\"168\" y=\"222\" text-anchor=\"middle\" font-size=\"9\" fill=\"#334155\">• Chất nền có DNA &amp; Ribosome</text>\n    <text x=\"168\" y=\"239\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#be123c\">→ Tạo năng lượng ATP</text>\n\n    <rect x=\"265\" y=\"160\" width=\"230\" height=\"104\" rx=\"12\" fill=\"#ffffff\" stroke=\"#16a34a\" stroke-width=\"2\"/>\n    <text x=\"380\" y=\"180\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"#15803d\">LỤC LẠP (QUANG HỢP)</text>\n    <ellipse cx=\"315\" cy=\"218\" rx=\"36\" ry=\"22\" fill=\"#dcfce7\" stroke=\"#16a34a\" stroke-width=\"2\"/>\n    <rect x=\"298\" y=\"208\" width=\"14\" height=\"6\" rx=\"2\" fill=\"#15803d\"/><rect x=\"298\" y=\"216\" width=\"14\" height=\"6\" rx=\"2\" fill=\"#15803d\"/>\n    <rect x=\"318\" y=\"210\" width=\"14\" height=\"6\" rx=\"2\" fill=\"#15803d\"/><rect x=\"318\" y=\"218\" width=\"14\" height=\"6\" rx=\"2\" fill=\"#15803d\"/>\n    <text x=\"415\" y=\"205\" text-anchor=\"middle\" font-size=\"9\" fill=\"#334155\">• Màng kép trơn, Thylakoid</text>\n    <text x=\"415\" y=\"222\" text-anchor=\"middle\" font-size=\"9\" fill=\"#334155\">• Chứa Diệp lục &amp; Stroma</text>\n    <text x=\"415\" y=\"239\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#15803d\">→ Chuyển quang năng → Hoá năng</text>\n\n    <rect x=\"510\" y=\"160\" width=\"230\" height=\"104\" rx=\"12\" fill=\"#ffffff\" stroke=\"#0284c7\" stroke-width=\"2\"/>\n    <text x=\"625\" y=\"180\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"#0369a1\">PHÂN BIỆT THỰC VẬT – ĐỘNG VẬT</text>\n    <text x=\"625\" y=\"203\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#15803d\" font-weight=\"700\">🌿 Thực vật: Thành Cellulose, Lục lạp,</text>\n    <text x=\"625\" y=\"218\" text-anchor=\"middle\" font-size=\"9\" fill=\"#334155\">Không bào trung tâm lớn, Cầu sinh chất</text>\n    <text x=\"625\" y=\"236\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#0369a1\" font-weight=\"700\">🐾 Động vật: Không thành, có Trung thể,</text>\n    <text x=\"625\" y=\"251\" text-anchor=\"middle\" font-size=\"9\" fill=\"#334155\">Lysosome rõ, Chất nền ngoại bào (ECM)</text>\n  </svg>",
  "9": "<svg viewBox=\"0 0 760 255\" class=\"w-full h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n    <rect width=\"760\" height=\"255\" rx=\"16\" fill=\"#f0fdf4\" class=\"dark:fill-slate-900\"/>\n    <text x=\"380\" y=\"26\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"800\" fill=\"#065f46\">THỰC HÀNH: QUY TRÌNH LÀM TIÊU BẢN &amp; QUAN SÁT TẾ BÀO DƯỚI KÍNH HIỂN VI</text>\n    <!-- Step 1: Cover slip 45 deg -->\n    <rect x=\"24\" y=\"46\" width=\"225\" height=\"188\" rx=\"12\" fill=\"#ffffff\" stroke=\"#0d9488\" stroke-width=\"2\"/>\n    <text x=\"136\" y=\"68\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"#0f766e\">1. KĨ THUẬT ĐẬY LAMEN 45°</text>\n    <rect x=\"52\" y=\"145\" width=\"168\" height=\"14\" rx=\"3\" fill=\"#bae6fd\" stroke=\"#0284c7\" stroke-width=\"1.5\"/>\n    <ellipse cx=\"136\" cy=\"142\" rx=\"22\" ry=\"6\" fill=\"#38bdf8\"/>\n    <line x1=\"115\" y1=\"142\" x2=\"165\" y2=\"95\" stroke=\"#0f766e\" stroke-width=\"3\"/>\n    <path d=\"M 145 142 A 28 28 0 0 0 136 122\" fill=\"none\" stroke=\"#e11d48\" stroke-width=\"1.5\"/>\n    <text x=\"156\" y=\"132\" font-size=\"10\" font-weight=\"800\" fill=\"#e11d48\">45°</text>\n    <text x=\"136\" y=\"182\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#334155\">Hạ từ từ lá kính (lamen) nghiêng 45°</text>\n    <text x=\"136\" y=\"198\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#0f766e\">→ Tránh tạo bọt khí trong tiêu bản</text>\n    <text x=\"136\" y=\"216\" text-anchor=\"middle\" font-size=\"9\" fill=\"#64748b\">Quan sát vật kính 10× trước → 40× sau</text>\n    <!-- Step 2: Plant Onion Epidermis -->\n    <rect x=\"268\" y=\"46\" width=\"225\" height=\"188\" rx=\"12\" fill=\"#ffffff\" stroke=\"#16a34a\" stroke-width=\"2\"/>\n    <text x=\"380\" y=\"68\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"#15803d\">2. BIỂU BÌ VẢY HÀNH (THỰC VẬT)</text>\n    <g stroke=\"#15803d\" stroke-width=\"2.5\" fill=\"#dcfce7\">\n      <polygon points=\"295,90 365,90 375,125 305,125\"/>\n      <polygon points=\"365,90 445,90 455,125 375,125\"/>\n      <polygon points=\"305,125 375,125 385,160 315,160\"/>\n      <polygon points=\"375,125 455,125 465,160 385,160\"/>\n    </g>\n    <circle cx=\"335\" cy=\"108\" r=\"6\" fill=\"#b45309\"/><circle cx=\"410\" cy=\"108\" r=\"6\" fill=\"#b45309\"/>\n    <circle cx=\"345\" cy=\"142\" r=\"6\" fill=\"#b45309\"/><circle cx=\"420\" cy=\"142\" r=\"6\" fill=\"#b45309\"/>\n    <text x=\"380\" y=\"182\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#334155\">• Nhuộm: Dung dịch Iodine (Lugol)</text>\n    <text x=\"380\" y=\"198\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#15803d\">• Hình đa giác dài xếp sát nhau</text>\n    <text x=\"380\" y=\"216\" text-anchor=\"middle\" font-size=\"9\" fill=\"#64748b\">Nhìn rõ: Thành cellulose, Nhân, Tế bào chất</text>\n    <!-- Step 3: Animal Cheek Cell -->\n    <rect x=\"512\" y=\"46\" width=\"225\" height=\"188\" rx=\"12\" fill=\"#ffffff\" stroke=\"#2563eb\" stroke-width=\"2\"/>\n    <text x=\"624\" y=\"68\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"#1d4ed8\">3. NIÊM MẠC MIỆNG (ĐỘNG VẬT)</text>\n    <ellipse cx=\"585\" cy=\"118\" rx=\"34\" ry=\"24\" fill=\"#dbeafe\" stroke=\"#2563eb\" stroke-width=\"2\"/>\n    <circle cx=\"585\" cy=\"118\" r=\"8\" fill=\"#1e40af\"/>\n    <ellipse cx=\"662\" cy=\"136\" rx=\"32\" ry=\"22\" fill=\"#dbeafe\" stroke=\"#2563eb\" stroke-width=\"2\"/>\n    <circle cx=\"662\" cy=\"136\" r=\"8\" fill=\"#1e40af\"/>\n    <text x=\"624\" y=\"182\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#334155\">• Nhuộm: Xanh Methylene + NaCl 0,9%</text>\n    <text x=\"624\" y=\"198\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#1d4ed8\">• Hình tròn/bầu dục mềm mại, rời rạc</text>\n    <text x=\"624\" y=\"216\" text-anchor=\"middle\" font-size=\"9\" fill=\"#64748b\">Không có thành tế bào; Nhân rõ ở trung tâm</text>\n  </svg>",
  "10": "<svg viewBox=\"0 0 760 280\" class=\"w-full h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n    <rect width=\"760\" height=\"280\" rx=\"16\" fill=\"#f0f9ff\" class=\"dark:fill-slate-900\"/>\n    <text x=\"380\" y=\"26\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"800\" fill=\"#0369a1\">CÁC PHƯƠNG THỨC VẬN CHUYỂN QUA MÀNG &amp; 3 MÔI TRƯỜNG THẨM THẤU</text>\n    <!-- Top Section: Transport Mechanisms -->\n    <rect x=\"20\" y=\"42\" width=\"720\" height=\"114\" rx=\"12\" fill=\"#ffffff\" stroke=\"#0284c7\" stroke-width=\"2\"/>\n    <!-- Membrane bar -->\n    <rect x=\"35\" y=\"88\" width=\"690\" height=\"24\" rx=\"4\" fill=\"#fde68a\" stroke=\"#d97706\" stroke-width=\"1.5\"/>\n    <text x=\"380\" y=\"104\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"800\" fill=\"#92400e\">LỚP KÉP PHOSPHOLIPID (MÀNG SINH CHẤT KHẢM ĐỘNG – THẤM CHỌN LỌC)</text>\n    <!-- 1. Simple diffusion -->\n    <text x=\"110\" y=\"60\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"800\" fill=\"#059669\">1. Khuếch tán đơn giản</text>\n    <text x=\"110\" y=\"75\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#334155\">O₂, CO₂, phân tử kị nước nhỏ</text>\n    <line x1=\"110\" y1=\"78\" x2=\"110\" y2=\"128\" stroke=\"#059669\" stroke-width=\"2.5\"/><polygon points=\"110,132 105,123 115,123\" fill=\"#059669\"/>\n    <text x=\"110\" y=\"145\" text-anchor=\"middle\" font-size=\"8.5\" font-weight=\"700\" fill=\"#059669\">Xuôi chiều nồng độ (0 ATP)</text>\n    <!-- 2. Facilitated diffusion -->\n    <rect x=\"268\" y=\"82\" width=\"24\" height=\"36\" rx=\"6\" fill=\"#38bdf8\" stroke=\"#0284c7\" stroke-width=\"1.5\"/>\n    <text x=\"280\" y=\"60\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"800\" fill=\"#0284c7\">2. Khuếch tán tăng cường</text>\n    <text x=\"280\" y=\"75\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#334155\">Ion, Glucose, H₂O (Aquaporin)</text>\n    <line x1=\"280\" y1=\"78\" x2=\"280\" y2=\"128\" stroke=\"#0284c7\" stroke-width=\"2.5\"/><polygon points=\"280,132 275,123 285,123\" fill=\"#0284c7\"/>\n    <text x=\"280\" y=\"145\" text-anchor=\"middle\" font-size=\"8.5\" font-weight=\"700\" fill=\"#0284c7\">Qua Kênh / Chất tải (0 ATP)</text>\n    <!-- 3. Active transport -->\n    <rect x=\"458\" y=\"82\" width=\"28\" height=\"36\" rx=\"6\" fill=\"#f43f5e\" stroke=\"#be123c\" stroke-width=\"1.5\"/>\n    <text x=\"472\" y=\"60\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"800\" fill=\"#e11d48\">3. Vận chuyển chủ động</text>\n    <text x=\"472\" y=\"75\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#334155\">Bơm Na⁺–K⁺, hấp thu khoáng</text>\n    <line x1=\"472\" y1=\"128\" x2=\"472\" y2=\"78\" stroke=\"#e11d48\" stroke-width=\"2.5\"/><polygon points=\"472,74 467,83 477,83\" fill=\"#e11d48\"/>\n    <text x=\"472\" y=\"145\" text-anchor=\"middle\" font-size=\"8.5\" font-weight=\"800\" fill=\"#e11d48\">Ngược gradient + CẦN ATP ⚡</text>\n    <!-- 4. Endo/Exocytosis -->\n    <text x=\"640\" y=\"60\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"800\" fill=\"#7c3aed\">4. Nhập bào &amp; Xuất bào</text>\n    <text x=\"640\" y=\"75\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#334155\">Thực bào, Ẩm bào, Túi tiết</text>\n    <circle cx=\"640\" cy=\"122\" r=\"10\" fill=\"#ddd6fe\" stroke=\"#7c3aed\" stroke-width=\"2\"/>\n    <text x=\"640\" y=\"145\" text-anchor=\"middle\" font-size=\"8.5\" font-weight=\"800\" fill=\"#7c3aed\">Biến dạng màng + CẦN ATP ⚡</text>\n\n    <!-- Bottom Section: 3 Osmotic Environments -->\n    <g transform=\"translate(20, 168)\" font-size=\"9.5\" text-anchor=\"middle\">\n      <rect x=\"0\" y=\"0\" width=\"230\" height=\"96\" rx=\"10\" fill=\"#ffffff\" stroke=\"#ef4444\" stroke-width=\"1.8\"/>\n      <text x=\"115\" y=\"20\" font-weight=\"800\" fill=\"#dc2626\">MÔI TRƯỜNG ƯU TRƯƠNG (C_ngoài &gt; C_trong)</text>\n      <text x=\"115\" y=\"40\" fill=\"#334155\">Nước đi ra ngoài → Tế bào mất nước</text>\n      <text x=\"115\" y=\"60\" font-weight=\"700\" fill=\"#dc2626\">• Hồng cầu: Co rúm / Nhăn nheo</text>\n      <text x=\"115\" y=\"78\" font-weight=\"700\" fill=\"#b45309\">• Thực vật: Co nguyên sinh (Tách màng)</text>\n\n      <rect x=\"245\" y=\"0\" width=\"230\" height=\"96\" rx=\"10\" fill=\"#ffffff\" stroke=\"#10b981\" stroke-width=\"1.8\"/>\n      <text x=\"360\" y=\"20\" font-weight=\"800\" fill=\"#059669\">MÔI TRƯỜNG ĐẲNG TRƯƠNG (C_ngoài = C_trong)</text>\n      <text x=\"360\" y=\"40\" fill=\"#334155\">Nước ra và vào tế bào cân bằng nhau</text>\n      <text x=\"360\" y=\"60\" font-weight=\"700\" fill=\"#059669\">• Hồng cầu: Hình đĩa lõm 2 mặt bình thường</text>\n      <text x=\"360\" y=\"78\" font-weight=\"700\" fill=\"#059669\">• Thực vật: Trạng thái bình thường</text>\n\n      <rect x=\"490\" y=\"0\" width=\"230\" height=\"96\" rx=\"10\" fill=\"#ffffff\" stroke=\"#0284c7\" stroke-width=\"1.8\"/>\n      <text x=\"605\" y=\"20\" font-weight=\"800\" fill=\"#0284c7\">MÔI TRƯỜNG NHƯỢC TRƯƠNG (C_ngoài &lt; C_trong)</text>\n      <text x=\"605\" y=\"40\" fill=\"#334155\">Nước thẩm thấu đi vào trong tế bào</text>\n      <text x=\"605\" y=\"60\" font-weight=\"700\" fill=\"#e11d48\">• Hồng cầu: Căng phồng → Vỡ (Tan máu)</text>\n      <text x=\"605\" y=\"78\" font-weight=\"700\" fill=\"#0284c7\">• Thực vật: Trương nước (Thành giữ không vỡ)</text>\n    </g>\n  </svg>",
  "11": "<svg viewBox=\"0 0 760 255\" class=\"w-full h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n    <rect width=\"760\" height=\"255\" rx=\"16\" fill=\"#fdf4ff\" class=\"dark:fill-slate-900\"/>\n    <text x=\"380\" y=\"26\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"800\" fill=\"#86198f\">THÍ NGHIỆM CO VÀ PHẢN CO NGUYÊN SINH Ở TẾ BÀO BIỂU BÌ LÁ THÀI LÀI TÍA</text>\n    <!-- State 1: Normal -->\n    <g transform=\"translate(22, 46)\">\n      <rect x=\"0\" y=\"0\" width=\"215\" height=\"190\" rx=\"12\" fill=\"#ffffff\" stroke=\"#a21caf\" stroke-width=\"2\"/>\n      <text x=\"107\" y=\"22\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"800\" fill=\"#86198f\">1. TẾ BÀO BÌNH THƯỜNG</text>\n      <polygon points=\"45,45 170,45 180,115 35,115\" fill=\"#f5d0fe\" stroke=\"#15803d\" stroke-width=\"4\"/>\n      <ellipse cx=\"107\" cy=\"80\" rx=\"55\" ry=\"26\" fill=\"#d946ef\" opacity=\"0.75\"/>\n      <text x=\"107\" y=\"84\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\">Không bào tím đầy</text>\n      <text x=\"107\" y=\"138\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#334155\">Màng sinh chất áp sát thành</text>\n      <text x=\"107\" y=\"156\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#15803d\">• Khí khổng: MỞ (Đủ sức trương)</text>\n      <text x=\"107\" y=\"174\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#64748b\">Môi trường nước cất ban đầu</text>\n    </g>\n    <!-- Arrow 1 -->\n    <text x=\"258\" y=\"125\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"800\" fill=\"#dc2626\">+ NaCl</text>\n    <text x=\"258\" y=\"142\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"900\" fill=\"#dc2626\">→</text>\n    <text x=\"258\" y=\"156\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#dc2626\">(Ưu trương)</text>\n    <!-- State 2: Plasmolysis -->\n    <g transform=\"translate(280, 46)\">\n      <rect x=\"0\" y=\"0\" width=\"215\" height=\"190\" rx=\"12\" fill=\"#ffffff\" stroke=\"#dc2626\" stroke-width=\"2.5\"/>\n      <text x=\"107\" y=\"22\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"800\" fill=\"#dc2626\">2. CO NGUYÊN SINH</text>\n      <polygon points=\"45,45 170,45 180,115 35,115\" fill=\"#f8fafc\" stroke=\"#15803d\" stroke-width=\"4\"/>\n      <ellipse cx=\"107\" cy=\"80\" rx=\"28\" ry=\"16\" fill=\"#a21caf\"/>\n      <text x=\"107\" y=\"83\" text-anchor=\"middle\" font-size=\"8.5\" font-weight=\"700\" fill=\"#fff\">Co tròn</text>\n      <text x=\"107\" y=\"138\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#334155\">Nước thoát ra → Màng tách khỏi thành</text>\n      <text x=\"107\" y=\"156\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#dc2626\">• Khí khổng: ĐÓNG (Mất sức trương)</text>\n      <text x=\"107\" y=\"174\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#64748b\">Màu tím đậm tập trung ở giữa</text>\n    </g>\n    <!-- Arrow 2 -->\n    <text x=\"516\" y=\"125\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"800\" fill=\"#0284c7\">+ H₂O cất</text>\n    <text x=\"516\" y=\"142\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"900\" fill=\"#0284c7\">→</text>\n    <text x=\"516\" y=\"156\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#0284c7\">(Nhược trương)</text>\n    <!-- State 3: Deplasmolysis -->\n    <g transform=\"translate(536, 46)\">\n      <rect x=\"0\" y=\"0\" width=\"202\" height=\"190\" rx=\"12\" fill=\"#ffffff\" stroke=\"#0284c7\" stroke-width=\"2\"/>\n      <text x=\"101\" y=\"22\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"800\" fill=\"#0369a1\">3. PHẢN CO NGUYÊN SINH</text>\n      <polygon points=\"40,45 162,45 172,115 30,115\" fill=\"#f5d0fe\" stroke=\"#15803d\" stroke-width=\"4\"/>\n      <ellipse cx=\"101\" cy=\"80\" rx=\"52\" ry=\"25\" fill=\"#d946ef\" opacity=\"0.75\"/>\n      <text x=\"101\" y=\"84\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"700\" fill=\"#fff\">Trương nước lại</text>\n      <text x=\"101\" y=\"138\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#334155\">Nước thẩm thấu ngược vào tế bào</text>\n      <text x=\"101\" y=\"156\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#0369a1\">• Khí khổng: MỞ TRỞ LẠI</text>\n      <text x=\"101\" y=\"174\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#e11d48\">Nếu tế bào chết → Không phản co</text>\n    </g>\n  </svg>",
  "12": "<svg viewBox=\"0 0 760 270\" class=\"w-full h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n    <rect width=\"760\" height=\"270\" rx=\"16\" fill=\"#f0fdfa\" class=\"dark:fill-slate-900\"/>\n    <text x=\"380\" y=\"26\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"800\" fill=\"#0f766e\">4 KIỂU TRUYỀN TIN GIỮA CÁC TẾ BÀO &amp; 3 GIAI ĐOẠN TRUYỀN TIN TẾ BÀO</text>\n    <!-- Top: 4 Modes of Cell Signaling -->\n    <g transform=\"translate(20, 42)\" font-size=\"9.5\" text-anchor=\"middle\">\n      <rect x=\"0\" y=\"0\" width=\"170\" height=\"68\" rx=\"10\" fill=\"#ffffff\" stroke=\"#0d9488\" stroke-width=\"1.8\"/>\n      <text x=\"85\" y=\"20\" font-weight=\"800\" fill=\"#0f766e\">1. Truyền tin trực tiếp</text>\n      <text x=\"85\" y=\"38\" fill=\"#334155\">Qua cầu sinh chất (TV) /</text>\n      <text x=\"85\" y=\"53\" fill=\"#0d9488\" font-weight=\"700\">Mối nối hở (ĐV) / Tiếp xúc màng</text>\n\n      <rect x=\"183\" y=\"0\" width=\"170\" height=\"68\" rx=\"10\" fill=\"#ffffff\" stroke=\"#0284c7\" stroke-width=\"1.8\"/>\n      <text x=\"268\" y=\"20\" font-weight=\"800\" fill=\"#0369a1\">2. Truyền tin cận tiết</text>\n      <text x=\"268\" y=\"38\" fill=\"#334155\">Khuếch tán dịch ngoại bào</text>\n      <text x=\"268\" y=\"53\" fill=\"#0284c7\" font-weight=\"700\">Đến các tế bào đích lân cận</text>\n\n      <rect x=\"366\" y=\"0\" width=\"170\" height=\"68\" rx=\"10\" fill=\"#ffffff\" stroke=\"#7c3aed\" stroke-width=\"1.8\"/>\n      <text x=\"451\" y=\"20\" font-weight=\"800\" fill=\"#6d28d9\">3. Truyền tin qua Synapse</text>\n      <text x=\"451\" y=\"38\" fill=\"#334155\">Chất dẫn truyền thần kinh</text>\n      <text x=\"451\" y=\"53\" fill=\"#7c3aed\" font-weight=\"700\">Qua khe synapse thần kinh – cơ</text>\n\n      <rect x=\"549\" y=\"0\" width=\"171\" height=\"68\" rx=\"10\" fill=\"#ffffff\" stroke=\"#e11d48\" stroke-width=\"1.8\"/>\n      <text x=\"634\" y=\"20\" font-weight=\"800\" fill=\"#be123c\">4. Truyền tin nội tiết (Xa)</text>\n      <text x=\"634\" y=\"38\" fill=\"#334155\">Hormone theo đường máu</text>\n      <text x=\"634\" y=\"53\" fill=\"#e11d48\" font-weight=\"700\">Đến tế bào đích ở xa trong cơ thể</text>\n    </g>\n    <!-- Bottom: 3 Stages of Signal Transduction -->\n    <rect x=\"20\" y=\"124\" width=\"720\" height=\"128\" rx=\"14\" fill=\"#ffffff\" stroke=\"#059669\" stroke-width=\"2\"/>\n    <text x=\"380\" y=\"146\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"800\" fill=\"#065f46\">3 GIAI ĐOẠN QUÁ TRÌNH TRUYỀN TIN TẾ BÀO</text>\n    <!-- Stage 1 -->\n    <rect x=\"40\" y=\"160\" width=\"195\" height=\"76\" rx=\"10\" fill=\"#ecfdf5\" stroke=\"#10b981\" stroke-width=\"2\"/>\n    <text x=\"137\" y=\"180\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"800\" fill=\"#047857\">GIAI ĐOẠN 1: TIẾP NHẬN</text>\n    <text x=\"137\" y=\"198\" text-anchor=\"middle\" font-size=\"9\" fill=\"#334155\">Phân tử tín hiệu gắn đặc hiệu vào</text>\n    <text x=\"137\" y=\"213\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"700\" fill=\"#065f46\">Thụ thể màng (ưa nước) hoặc</text>\n    <text x=\"137\" y=\"227\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"700\" fill=\"#065f46\">Thụ thể nội bào (Steroid kị nước)</text>\n    <text x=\"255\" y=\"204\" font-size=\"18\" font-weight=\"900\" fill=\"#059669\">→</text>\n    <!-- Stage 2 -->\n    <rect x=\"275\" y=\"160\" width=\"210\" height=\"76\" rx=\"10\" fill=\"#f0f9ff\" stroke=\"#0284c7\" stroke-width=\"2\"/>\n    <text x=\"380\" y=\"180\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"800\" fill=\"#0369a1\">GIAI ĐOẠN 2: TRUYỀN TÍN HIỆU</text>\n    <text x=\"380\" y=\"198\" text-anchor=\"middle\" font-size=\"9\" fill=\"#334155\">Thụ thể biến đổi cấu hình → Chuỗi</text>\n    <text x=\"380\" y=\"213\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"700\" fill=\"#0369a1\">phosphoryl hoá &amp; chất truyền tin thứ 2</text>\n    <text x=\"380\" y=\"227\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"700\" fill=\"#e11d48\">(cAMP, Ca²⁺) → KHUẾCH ĐẠI TÍN HIỆU</text>\n    <text x=\"505\" y=\"204\" font-size=\"18\" font-weight=\"900\" fill=\"#0284c7\">→</text>\n    <!-- Stage 3 -->\n    <rect x=\"525\" y=\"160\" width=\"195\" height=\"76\" rx=\"10\" fill=\"#fef3c7\" stroke=\"#d97706\" stroke-width=\"2\"/>\n    <text x=\"622\" y=\"180\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"800\" fill=\"#b45309\">GIAI ĐOẠN 3: ĐÁP ỨNG</text>\n    <text x=\"622\" y=\"198\" text-anchor=\"middle\" font-size=\"9\" fill=\"#334155\">Khởi động đáp ứng tế bào đích:</text>\n    <text x=\"622\" y=\"213\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"700\" fill=\"#b45309\">• Phiên mã biểu hiện gene trong nhân</text>\n    <text x=\"622\" y=\"227\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"700\" fill=\"#b45309\">• Hoạt hoá enzyme / Phân chia / Co cơ</text>\n  </svg>",
  "13": "<svg viewBox=\"0 0 760 275\" class=\"w-full h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n    <rect width=\"760\" height=\"275\" rx=\"16\" fill=\"#fffbeb\" class=\"dark:fill-slate-900\"/>\n    <text x=\"380\" y=\"26\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"800\" fill=\"#b45309\">CHU TRÌNH ĐỒNG TIỀN NĂNG LƯỢNG ATP &amp; CƠ CHẾ XÚC TÁC – ĐIỀU HOÀ ENZYME</text>\n    <!-- Left Box: ATP - ADP Cycle -->\n    <rect x=\"20\" y=\"44\" width=\"340\" height=\"212\" rx=\"12\" fill=\"#ffffff\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n    <text x=\"190\" y=\"66\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"#b45309\">1. CHU TRÌNH NĂNG LƯỢNG ATP ⇄ ADP</text>\n    <rect x=\"125\" y=\"80\" width=\"130\" height=\"36\" rx=\"8\" fill=\"#fef3c7\" stroke=\"#d97706\" stroke-width=\"2\"/>\n    <text x=\"190\" y=\"96\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"800\" fill=\"#b45309\">ATP (3 nhóm P)</text>\n    <text x=\"190\" y=\"110\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#92400e\">Adenine + Ribose + P~P~P</text>\n    <!-- Arrows -->\n    <path d=\"M 260 98 Q 315 135, 260 172\" fill=\"none\" stroke=\"#dc2626\" stroke-width=\"2.5\"/>\n    <polygon points=\"258,172 267,166 265,176\" fill=\"#dc2626\"/>\n    <text x=\"305\" y=\"132\" text-anchor=\"middle\" font-size=\"8.5\" font-weight=\"800\" fill=\"#dc2626\">Thuỷ phân</text>\n    <text x=\"305\" y=\"145\" text-anchor=\"middle\" font-size=\"8\" fill=\"#334155\">Cung cấp NL cho</text>\n    <text x=\"305\" y=\"157\" text-anchor=\"middle\" font-size=\"8\" font-weight=\"700\" fill=\"#dc2626\">Đồng hoá, Bơm, Co cơ</text>\n\n    <path d=\"M 120 172 Q 65 135, 120 98\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\"/>\n    <polygon points=\"122,98 113,104 115,94\" fill=\"#059669\"/>\n    <text x=\"72\" y=\"132\" text-anchor=\"middle\" font-size=\"8.5\" font-weight=\"800\" fill=\"#059669\">Tổng hợp</text>\n    <text x=\"72\" y=\"145\" text-anchor=\"middle\" font-size=\"8\" fill=\"#334155\">Năng lượng từ</text>\n    <text x=\"72\" y=\"157\" text-anchor=\"middle\" font-size=\"8\" font-weight=\"700\" fill=\"#059669\">Dị hoá (Hô hấp/QH)</text>\n\n    <rect x=\"125\" y=\"160\" width=\"130\" height=\"34\" rx=\"8\" fill=\"#e0f2fe\" stroke=\"#0284c7\" stroke-width=\"2\"/>\n    <text x=\"190\" y=\"181\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"800\" fill=\"#0369a1\">ADP + Pᵢ + Năng lượng</text>\n    <text x=\"190\" y=\"218\" text-anchor=\"middle\" font-size=\"9\" fill=\"#334155\">Liên kết cao năng P~P ngoài cùng dễ đứt</text>\n    <text x=\"190\" y=\"236\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"700\" fill=\"#b45309\">ATP không dùng dự trữ dài hạn, tái tạo liên tục</text>\n\n    <!-- Right Box: Enzyme & Feedback Inhibition -->\n    <rect x=\"378\" y=\"44\" width=\"362\" height=\"212\" rx=\"12\" fill=\"#ffffff\" stroke=\"#059669\" stroke-width=\"2\"/>\n    <text x=\"559\" y=\"66\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"#065f46\">2. CƠ CHẾ XÚC TÁC ENZYME &amp; ỨC CHẾ NGƯỢC</text>\n    <rect x=\"394\" y=\"80\" width=\"330\" height=\"58\" rx=\"8\" fill=\"#ecfdf5\" stroke=\"#10b981\"/>\n    <text x=\"559\" y=\"100\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"800\" fill=\"#047857\">E (Trung tâm hoạt động) + Cơ chất (S) ⇄ Phức hợp E–S → E + Sản phẩm (P)</text>\n    <text x=\"559\" y=\"118\" text-anchor=\"middle\" font-size=\"9\" fill=\"#334155\">Giảm năng lượng hoạt hoá E_a • Đặc hiệu cao • Nhiệt/pH quá cao gây biến tính</text>\n    <!-- Feedback Inhibition Diagram -->\n    <text x=\"559\" y=\"158\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"800\" fill=\"#be123c\">ĐIỀU HOÀ CHUYỂN HOÁ BẰNG ỨC CHẾ NGƯỢC (FEEDBACK INHIBITION)</text>\n    <g font-size=\"9.5\" font-weight=\"700\" text-anchor=\"middle\">\n      <rect x=\"398\" y=\"170\" width=\"66\" height=\"32\" rx=\"6\" fill=\"#e0f2fe\" stroke=\"#0284c7\"/><text x=\"431\" y=\"190\" fill=\"#0369a1\">Chất đầu A</text>\n      <text x=\"482\" y=\"182\" font-size=\"8.5\" fill=\"#059669\">E₁</text><text x=\"482\" y=\"194\" font-size=\"13\" fill=\"#059669\">→</text>\n      <rect x=\"500\" y=\"170\" width=\"54\" height=\"32\" rx=\"6\" fill=\"#f1f5f9\" stroke=\"#64748b\"/><text x=\"527\" y=\"190\" fill=\"#334155\">Chất B</text>\n      <text x=\"570\" y=\"182\" font-size=\"8.5\" fill=\"#059669\">E₂</text><text x=\"570\" y=\"194\" font-size=\"13\" fill=\"#059669\">→</text>\n      <rect x=\"586\" y=\"170\" width=\"54\" height=\"32\" rx=\"6\" fill=\"#f1f5f9\" stroke=\"#64748b\"/><text x=\"613\" y=\"190\" fill=\"#334155\">Chất C</text>\n      <text x=\"655\" y=\"182\" font-size=\"8.5\" fill=\"#059669\">E₃</text><text x=\"655\" y=\"194\" font-size=\"13\" fill=\"#059669\">→</text>\n      <rect x=\"670\" y=\"170\" width=\"56\" height=\"32\" rx=\"6\" fill=\"#ffe4e6\" stroke=\"#e11d48\"/><text x=\"698\" y=\"190\" fill=\"#be123c\">Đích P</text>\n    </g>\n    <path d=\"M 698 202 L 698 232 L 482 232 L 482 200\" fill=\"none\" stroke=\"#e11d48\" stroke-width=\"2\" stroke-dasharray=\"4 3\"/>\n    <text x=\"590\" y=\"246\" text-anchor=\"middle\" font-size=\"8.5\" font-weight=\"700\" fill=\"#be123c\">Khi sản phẩm P dư thừa → Quay lại ức chế dị lập thể Enzyme E₁</text>\n  </svg>",
  "14": "<svg viewBox=\"0 0 760 280\" class=\"w-full h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n    <rect width=\"760\" height=\"280\" rx=\"16\" fill=\"#f0fdf4\" class=\"dark:fill-slate-900\"/>\n    <text x=\"380\" y=\"25\" text-anchor=\"middle\" font-size=\"13.5\" font-weight=\"800\" fill=\"#065f46\">SƠ ĐỒ LIÊN KẾT HÔ HẤP TẾ BÀO – LÊN MEN &amp; QUANG HỢP TRONG TẾ BÀO NHÂN THỰC</text>\n    <!-- Left Box: Cellular Respiration & Fermentation -->\n    <rect x=\"18\" y=\"42\" width=\"352\" height=\"222\" rx=\"12\" fill=\"#ffffff\" stroke=\"#e11d48\" stroke-width=\"2\"/>\n    <text x=\"194\" y=\"62\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"#be123c\">1. PHÂN GIẢI CHẤT HỮU CƠ (HÔ HẤP &amp; LÊN MEN)</text>\n    <rect x=\"32\" y=\"74\" width=\"324\" height=\"40\" rx=\"8\" fill=\"#ffe4e6\" stroke=\"#f43f5e\"/>\n    <text x=\"194\" y=\"91\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"800\" fill=\"#be123c\">① ĐƯỜNG PHÂN (Tại Tế bào chất / Bào tương)</text>\n    <text x=\"194\" y=\"106\" text-anchor=\"middle\" font-size=\"9\" fill=\"#334155\">1 Glucose (6C) → 2 Pyruvate (3C) + 2 NADH + <tspan font-weight=\"800\" fill=\"#be123c\">2 ATP</tspan></text>\n    <!-- Branch left: Aerobic in Mitochondria -->\n    <rect x=\"32\" y=\"124\" width=\"200\" height=\"126\" rx=\"8\" fill=\"#fff1f2\" stroke=\"#e11d48\" stroke-width=\"1.5\"/>\n    <text x=\"132\" y=\"142\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"800\" fill=\"#9f1239\">Có O₂: HÔ HẤP HIẾU KHÍ (Ti thể)</text>\n    <text x=\"132\" y=\"160\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#334155\">② Oxy hoá Pyruvate → Acetyl-CoA</text>\n    <text x=\"132\" y=\"176\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#334155\">&amp; Chu trình Krebs (Chất nền): <tspan font-weight=\"700\">2 ATP</tspan></text>\n    <text x=\"132\" y=\"194\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#334155\">③ Chuỗi truyền e⁻ (Màng trong):</text>\n    <text x=\"132\" y=\"210\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"800\" fill=\"#be123c\">O₂ nhận e⁻ → H₂O + 26–28 ATP</text>\n    <text x=\"132\" y=\"234\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"800\" fill=\"#047857\">Tổng: 30 – 32 ATP / 1 Glucose</text>\n    <!-- Branch right: Fermentation -->\n    <rect x=\"240\" y=\"124\" width=\"116\" height=\"126\" rx=\"8\" fill=\"#fef3c7\" stroke=\"#d97706\" stroke-width=\"1.5\"/>\n    <text x=\"298\" y=\"142\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"800\" fill=\"#b45309\">Thiếu O₂: LÊN MEN</text>\n    <text x=\"298\" y=\"160\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#334155\">Tại Bào tương</text>\n    <text x=\"298\" y=\"178\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#334155\">Tái sinh NAD⁺:</text>\n    <text x=\"298\" y=\"195\" text-anchor=\"middle\" font-size=\"8.5\" font-weight=\"700\" fill=\"#92400e\">• Lactate (Sữa chua)</text>\n    <text x=\"298\" y=\"211\" text-anchor=\"middle\" font-size=\"8.5\" font-weight=\"700\" fill=\"#92400e\">• Ethanol + CO₂</text>\n    <text x=\"298\" y=\"234\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"800\" fill=\"#b45309\">Tổng: Chỉ 2 ATP</text>\n\n    <!-- Right Box: Photosynthesis -->\n    <rect x=\"386\" y=\"42\" width=\"356\" height=\"222\" rx=\"12\" fill=\"#ffffff\" stroke=\"#16a34a\" stroke-width=\"2\"/>\n    <text x=\"564\" y=\"62\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"#15803d\">2. TỔNG HỢP CHẤT HỮU CƠ: QUANG HỢP (LỤC LẠP)</text>\n    <!-- Light Reactions -->\n    <rect x=\"402\" y=\"76\" width=\"150\" height=\"132\" rx=\"10\" fill=\"#dcfce7\" stroke=\"#16a34a\" stroke-width=\"1.8\"/>\n    <text x=\"477\" y=\"96\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"800\" fill=\"#15803d\">PHA SÁNG</text>\n    <text x=\"477\" y=\"112\" text-anchor=\"middle\" font-size=\"8.5\" font-weight=\"700\" fill=\"#047857\">(Màng Thylakoid)</text>\n    <text x=\"477\" y=\"132\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#334155\">• Diệp lục hấp thu ánh sáng</text>\n    <text x=\"477\" y=\"148\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#334155\">• Quang phân li H₂O</text>\n    <text x=\"477\" y=\"166\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"800\" fill=\"#0284c7\">→ Giải phóng khí O₂↑</text>\n    <text x=\"477\" y=\"186\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"800\" fill=\"#be123c\">→ Tạo ATP &amp; NADPH</text>\n    <!-- Arrows between Light and Calvin -->\n    <text x=\"565\" y=\"128\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"900\" fill=\"#be123c\">→</text>\n    <text x=\"565\" y=\"165\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"900\" fill=\"#0284c7\">←</text>\n    <!-- Calvin Cycle -->\n    <rect x=\"578\" y=\"76\" width=\"150\" height=\"132\" rx=\"10\" fill=\"#ecfdf5\" stroke=\"#0d9488\" stroke-width=\"1.8\"/>\n    <text x=\"653\" y=\"96\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"800\" fill=\"#0f766e\">CHU TRÌNH CALVIN</text>\n    <text x=\"653\" y=\"112\" text-anchor=\"middle\" font-size=\"8.5\" font-weight=\"700\" fill=\"#0d9488\">(Chất nền Stroma)</text>\n    <text x=\"653\" y=\"132\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#334155\">• Nhận CO₂ từ khí quyển</text>\n    <text x=\"653\" y=\"148\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#334155\">• Dùng ATP &amp; NADPH</text>\n    <text x=\"653\" y=\"166\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"800\" fill=\"#065f46\">→ Tạo C₆H₁₂O₆ (Glucose)</text>\n    <text x=\"653\" y=\"186\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#0369a1\">Trả lại ADP + Pᵢ, NADP⁺</text>\n    <!-- Bottom note -->\n    <rect x=\"402\" y=\"218\" width=\"326\" height=\"32\" rx=\"6\" fill=\"#f0fdf4\" stroke=\"#86efac\"/>\n    <text x=\"565\" y=\"238\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"700\" fill=\"#166534\">6CO₂ + 6H₂O + Quang năng → C₆H₁₂O₆ + 6O₂ (Tích luỹ hoá năng)</text>\n  </svg>",
  "15": "<svg viewBox=\"0 0 760 255\" class=\"w-full h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n    <rect width=\"760\" height=\"255\" rx=\"16\" fill=\"#f0f9ff\" class=\"dark:fill-slate-900\"/>\n    <text x=\"380\" y=\"26\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"800\" fill=\"#0369a1\">THỰC HÀNH: ẢNH HƯỞNG CỦA NHIỆT ĐỘ, pH ĐẾN HOẠT TÍNH ENZYME &amp; AMYLASE</text>\n    <!-- Left Chart: Temperature Curve -->\n    <rect x=\"22\" y=\"45\" width=\"235\" height=\"192\" rx=\"12\" fill=\"#ffffff\" stroke=\"#0284c7\" stroke-width=\"2\"/>\n    <text x=\"139\" y=\"66\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"800\" fill=\"#0369a1\">1. ĐỒ THỊ THEO NHIỆT ĐỘ (t°C)</text>\n    <line x1=\"48\" y1=\"190\" x2=\"232\" y2=\"190\" stroke=\"#475569\" stroke-width=\"2\"/>\n    <line x1=\"48\" y1=\"190\" x2=\"48\" y2=\"85\" stroke=\"#475569\" stroke-width=\"2\"/>\n    <path d=\"M 52 182 Q 115 160, 152 94 Q 178 94, 198 188\" fill=\"none\" stroke=\"#e11d48\" stroke-width=\"3\"/>\n    <line x1=\"152\" y1=\"94\" x2=\"152\" y2=\"190\" stroke=\"#059669\" stroke-width=\"1.5\" stroke-dasharray=\"3 3\"/>\n    <text x=\"152\" y=\"88\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"800\" fill=\"#059669\">Tối ưu (~37°C)</text>\n    <text x=\"65\" y=\"205\" font-size=\"8.5\" fill=\"#334155\">0°C (Bất hoạt)</text>\n    <text x=\"195\" y=\"205\" font-size=\"8.5\" fill=\"#dc2626\" font-weight=\"700\">&gt;60°C (Biến tính)</text>\n    <text x=\"139\" y=\"224\" text-anchor=\"middle\" font-size=\"9\" fill=\"#475569\">Nhiệt cao phá vỡ cấu hình 3D vĩnh viễn</text>\n\n    <!-- Center Chart: pH Curve -->\n    <rect x=\"272\" y=\"45\" width=\"220\" height=\"192\" rx=\"12\" fill=\"#ffffff\" stroke=\"#0d9488\" stroke-width=\"2\"/>\n    <text x=\"382\" y=\"66\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"800\" fill=\"#0f766e\">2. ĐỒ THỊ THEO ĐỘ pH</text>\n    <line x1=\"295\" y1=\"190\" x2=\"472\" y2=\"190\" stroke=\"#475669\" stroke-width=\"2\"/>\n    <line x1=\"295\" y1=\"190\" x2=\"295\" y2=\"85\" stroke=\"#475669\" stroke-width=\"2\"/>\n    <!-- Pepsin pH 2 -->\n    <path d=\"M 302 188 Q 325 95, 348 188\" fill=\"none\" stroke=\"#d97706\" stroke-width=\"2.5\"/>\n    <text x=\"325\" y=\"92\" text-anchor=\"middle\" font-size=\"8.5\" font-weight=\"800\" fill=\"#b45309\">Pepsin (pH~2)</text>\n    <!-- Amylase pH 7 -->\n    <path d=\"M 355 188 Q 392 95, 428 188\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\"/>\n    <text x=\"392\" y=\"108\" text-anchor=\"middle\" font-size=\"8.5\" font-weight=\"800\" fill=\"#059669\">Amylase (pH~7)</text>\n    <text x=\"382\" y=\"206\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#334155\">pH:  1    2    4    6    7    8    10</text>\n    <text x=\"382\" y=\"224\" text-anchor=\"middle\" font-size=\"9\" fill=\"#475569\">Mỗi enzyme có pH tối ưu đặc trưng</text>\n\n    <!-- Right Box: Amylase + Iodine Test -->\n    <rect x=\"506\" y=\"45\" width=\"232\" height=\"192\" rx=\"12\" fill=\"#ffffff\" stroke=\"#7c3aed\" stroke-width=\"2\"/>\n    <text x=\"622\" y=\"66\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"800\" fill=\"#6d28d9\">3. KIỂM TRA AMYLASE + LUGOL</text>\n    <rect x=\"522\" y=\"80\" width=\"200\" height=\"62\" rx=\"8\" fill=\"#fef3c7\" stroke=\"#d97706\"/>\n    <text x=\"622\" y=\"98\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"800\" fill=\"#b45309\">Ống 37°C (pH 7): MẤT MÀU XANH</text>\n    <text x=\"622\" y=\"114\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#334155\">Tinh bột đã bị Amylase thuỷ phân</text>\n    <text x=\"622\" y=\"129\" text-anchor=\"middle\" font-size=\"8.5\" font-weight=\"700\" fill=\"#059669\">thành đường Maltose hoàn toàn</text>\n\n    <rect x=\"522\" y=\"152\" width=\"200\" height=\"68\" rx=\"8\" fill=\"#dbeafe\" stroke=\"#2563eb\"/>\n    <text x=\"622\" y=\"170\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"800\" fill=\"#1e3a8a\">Ống Đun sôi 100°C / Nước đá:</text>\n    <text x=\"622\" y=\"186\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"800\" fill=\"#1d4ed8\">CÒN MÀU XANH TÍM ĐẬM</text>\n    <text x=\"622\" y=\"204\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#334155\">Tinh bột chưa bị phân giải</text>\n  </svg>",
  "16": "<svg viewBox=\"0 0 760 275\" class=\"w-full h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n    <rect width=\"760\" height=\"275\" rx=\"16\" fill=\"#f0fdf4\" class=\"dark:fill-slate-900\"/>\n    <text x=\"380\" y=\"26\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"800\" fill=\"#065f46\">CHU KÌ TẾ BÀO (G₁ – S – G₂ – M), ĐIỂM KIỂM SOÁT &amp; 4 KÌ NGUYÊN PHÂN</text>\n    <!-- Left: Cell Cycle Wheel -->\n    <rect x=\"20\" y=\"44\" width=\"250\" height=\"214\" rx=\"12\" fill=\"#ffffff\" stroke=\"#059669\" stroke-width=\"2\"/>\n    <text x=\"145\" y=\"64\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"#065f46\">1. VÒNG CHU KÌ TẾ BÀO</text>\n    <circle cx=\"145\" cy=\"145\" r=\"58\" fill=\"none\" stroke=\"#10b981\" stroke-width=\"18\"/>\n    <path d=\"M 145 87 A 58 58 0 0 1 203 145\" fill=\"none\" stroke=\"#f59e0b\" stroke-width=\"18\"/>\n    <text x=\"145\" y=\"142\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"800\" fill=\"#065f46\">KÌ TRUNG GIAN</text>\n    <text x=\"145\" y=\"156\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"700\" fill=\"#047857\">G₁ → S → G₂ (90%)</text>\n    <text x=\"205\" y=\"95\" font-size=\"9.5\" font-weight=\"800\" fill=\"#d97706\">Pha M</text>\n    <text x=\"82\" y=\"102\" font-size=\"9.5\" font-weight=\"800\" fill=\"#047857\">Pha G₂</text>\n    <text x=\"80\" y=\"195\" font-size=\"9.5\" font-weight=\"800\" fill=\"#0284c7\">Pha S (x2 DNA)</text>\n    <text x=\"195\" y=\"195\" font-size=\"9.5\" font-weight=\"800\" fill=\"#059669\">Pha G₁</text>\n    <text x=\"145\" y=\"226\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"700\" fill=\"#e11d48\">🛑 3 Điểm kiểm soát: G₁/S • G₂/M • Thoi</text>\n    <text x=\"145\" y=\"242\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#64748b\">Mất kiểm soát → Khối u / Ung thư</text>\n\n    <!-- Right: 4 Stages of Mitosis -->\n    <rect x=\"285\" y=\"44\" width=\"455\" height=\"214\" rx=\"12\" fill=\"#ffffff\" stroke=\"#0d9488\" stroke-width=\"2\"/>\n    <text x=\"512\" y=\"64\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"#0f766e\">2. BỐN KÌ NGUYÊN PHÂN (TỪ 1 TẾ BÀO 2n → 2 TẾ BÀO CON 2n GIỐNG HỆT MẸ)</text>\n    <!-- Prophase -->\n    <g transform=\"translate(300, 78)\" text-anchor=\"middle\">\n      <rect x=\"0\" y=\"0\" width=\"98\" height=\"122\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#94a3b8\"/>\n      <text x=\"49\" y=\"18\" font-size=\"10\" font-weight=\"800\" fill=\"#0f766e\">1. KÌ ĐẦU</text>\n      <circle cx=\"49\" cy=\"58\" r=\"26\" fill=\"#ecfdf5\" stroke=\"#059669\" stroke-dasharray=\"4 2\" stroke-width=\"1.8\"/>\n      <text x=\"49\" y=\"62\" font-size=\"14\" font-weight=\"800\" fill=\"#dc2626\">XX</text>\n      <text x=\"49\" y=\"98\" font-size=\"8.5\" fill=\"#334155\">NST kép co xoắn</text>\n      <text x=\"49\" y=\"112\" font-size=\"8.5\" fill=\"#64748b\">Màng nhân tiêu biến</text>\n    </g>\n    <!-- Metaphase -->\n    <g transform=\"translate(408, 78)\" text-anchor=\"middle\">\n      <rect x=\"0\" y=\"0\" width=\"98\" height=\"122\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#0284c7\" stroke-width=\"1.5\"/>\n      <text x=\"49\" y=\"18\" font-size=\"10\" font-weight=\"800\" fill=\"#0369a1\">2. KÌ GIỮA</text>\n      <circle cx=\"49\" cy=\"58\" r=\"26\" fill=\"#f0f9ff\" stroke=\"#0284c7\" stroke-width=\"1.8\"/>\n      <line x1=\"23\" y1=\"58\" x2=\"75\" y2=\"58\" stroke=\"#94a3b8\" stroke-dasharray=\"2 2\"/>\n      <text x=\"49\" y=\"62\" font-size=\"13\" font-weight=\"800\" fill=\"#dc2626\">X X</text>\n      <text x=\"49\" y=\"98\" font-size=\"8.5\" font-weight=\"700\" fill=\"#0369a1\">Xếp 1 hàng xích đạo</text>\n      <text x=\"49\" y=\"112\" font-size=\"8.5\" fill=\"#64748b\">Xoắn cực đại rõ nhất</text>\n    </g>\n    <!-- Anaphase -->\n    <g transform=\"translate(516, 78)\" text-anchor=\"middle\">\n      <rect x=\"0\" y=\"0\" width=\"98\" height=\"122\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#e11d48\" stroke-width=\"1.5\"/>\n      <text x=\"49\" y=\"18\" font-size=\"10\" font-weight=\"800\" fill=\"#be123c\">3. KÌ SAU</text>\n      <ellipse cx=\"49\" cy=\"58\" rx=\"28\" ry=\"24\" fill=\"#fff1f2\" stroke=\"#e11d48\" stroke-width=\"1.8\"/>\n      <text x=\"49\" y=\"50\" font-size=\"11\" font-weight=\"800\" fill=\"#dc2626\">∧ ∧</text>\n      <text x=\"49\" y=\"72\" font-size=\"11\" font-weight=\"800\" fill=\"#dc2626\">∨ ∨</text>\n      <text x=\"49\" y=\"98\" font-size=\"8.5\" font-weight=\"700\" fill=\"#be123c\">Tách chromatid chị em</text>\n      <text x=\"49\" y=\"112\" font-size=\"8.5\" fill=\"#64748b\">Phân li về 2 cực (4n đơn)</text>\n    </g>\n    <!-- Telophase -->\n    <g transform=\"translate(624, 78)\" text-anchor=\"middle\">\n      <rect x=\"0\" y=\"0\" width=\"100\" height=\"122\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#059669\" stroke-width=\"1.5\"/>\n      <text x=\"50\" y=\"18\" font-size=\"10\" font-weight=\"800\" fill=\"#065f46\">4. KÌ CUỐI</text>\n      <circle cx=\"34\" cy=\"58\" r=\"16\" fill=\"#d1fae5\" stroke=\"#059669\" stroke-width=\"1.8\"/>\n      <circle cx=\"66\" cy=\"58\" r=\"16\" fill=\"#d1fae5\" stroke=\"#059669\" stroke-width=\"1.8\"/>\n      <text x=\"34\" y=\"61\" font-size=\"9\" font-weight=\"800\" fill=\"#065f46\">2n</text>\n      <text x=\"66\" y=\"61\" font-size=\"9\" font-weight=\"800\" fill=\"#065f46\">2n</text>\n      <text x=\"50\" y=\"98\" font-size=\"8.5\" font-weight=\"700\" fill=\"#065f46\">NST dãn xoắn, 2 nhân</text>\n      <text x=\"50\" y=\"112\" font-size=\"8.5\" fill=\"#64748b\">Chia TBC: Thắt eo / Vách</text>\n    </g>\n    <text x=\"512\" y=\"222\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#0f766e\">• Động vật: Thắt eo màng sinh chất từ ngoài vào   • Thực vật: Hình thành vách ngăn từ trong ra</text>\n    <text x=\"512\" y=\"242\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"800\" fill=\"#047857\">Ý nghĩa: Sinh trưởng, thay thế tế bào già/tổn thương, tái sinh và cơ sở sinh sản vô tính</text>\n  </svg>",
  "17": "<svg viewBox=\"0 0 760 270\" class=\"w-full h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n    <rect width=\"760\" height=\"270\" rx=\"16\" fill=\"#fdf4ff\" class=\"dark:fill-slate-900\"/>\n    <text x=\"380\" y=\"26\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"800\" fill=\"#7e22ce\">SƠ ĐỒ GIẢM PHÂN TẠO GIAO TỬ &amp; CƠ CHẾ PHÁT SINH BIẾN DỊ TỔ HỢP (2n → 4n đơn)</text>\n    <!-- Cell 2n parent -->\n    <g transform=\"translate(20, 56)\" text-anchor=\"middle\">\n      <rect x=\"0\" y=\"0\" width=\"120\" height=\"145\" rx=\"12\" fill=\"#ffffff\" stroke=\"#9333ea\" stroke-width=\"2\"/>\n      <text x=\"60\" y=\"22\" font-size=\"10\" font-weight=\"800\" fill=\"#6b21a8\">TẾ BÀO MẸ (2n)</text>\n      <circle cx=\"60\" cy=\"68\" r=\"28\" fill=\"#f3e8ff\" stroke=\"#9333ea\" stroke-width=\"2\"/>\n      <text x=\"60\" y=\"72\" font-size=\"12\" font-weight=\"800\" fill=\"#7e22ce\">2n đơn</text>\n      <text x=\"60\" y=\"114\" font-size=\"8.5\" font-weight=\"700\" fill=\"#0284c7\">Nhân đôi DNA 1 lần</text>\n      <text x=\"60\" y=\"130\" font-size=\"8.5\" fill=\"#334155\">trước Giảm phân I</text>\n    </g>\n    <text x=\"152\" y=\"132\" font-size=\"16\" font-weight=\"900\" fill=\"#9333ea\">→</text>\n    <!-- Meiosis I -->\n    <g transform=\"translate(166, 46)\" text-anchor=\"middle\">\n      <rect x=\"0\" y=\"0\" width=\"215\" height=\"165\" rx=\"12\" fill=\"#ffffff\" stroke=\"#e11d48\" stroke-width=\"2.5\"/>\n      <text x=\"107\" y=\"22\" font-size=\"10.5\" font-weight=\"800\" fill=\"#be123c\">GIẢM PHÂN I (GIẢM NHIỄM)</text>\n      <rect x=\"14\" y=\"34\" width=\"187\" height=\"72\" rx=\"8\" fill=\"#fff1f2\" stroke=\"#f43f5e\"/>\n      <text x=\"107\" y=\"52\" font-size=\"9.5\" font-weight=\"800\" fill=\"#be123c\">• Kì đầu I: Tiếp hợp &amp; Trao đổi chéo</text>\n      <text x=\"107\" y=\"69\" font-size=\"9.5\" font-weight=\"800\" fill=\"#0369a1\">• Kì giữa I: Xếp thành 2 HÀNG</text>\n      <text x=\"107\" y=\"86\" font-size=\"9.5\" font-weight=\"700\" fill=\"#334155\">• Kì sau I: Tách cặp NST tương đồng</text>\n      <circle cx=\"68\" cy=\"134\" r=\"20\" fill=\"#ffe4e6\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"68\" y=\"138\" font-size=\"9.5\" font-weight=\"800\" fill=\"#be123c\">n kép</text>\n      <circle cx=\"146\" cy=\"134\" r=\"20\" fill=\"#ffe4e6\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"146\" y=\"138\" font-size=\"9.5\" font-weight=\"800\" fill=\"#be123c\">n kép</text>\n    </g>\n    <text x=\"394\" y=\"132\" font-size=\"16\" font-weight=\"900\" fill=\"#059669\">→</text>\n    <!-- Meiosis II -->\n    <g transform=\"translate(408, 46)\" text-anchor=\"middle\">\n      <rect x=\"0\" y=\"0\" width=\"332\" height=\"165\" rx=\"12\" fill=\"#ffffff\" stroke=\"#059669\" stroke-width=\"2\"/>\n      <text x=\"166\" y=\"22\" font-size=\"10.5\" font-weight=\"800\" fill=\"#065f46\">GIẢM PHÂN II (KHÔNG NHÂN ĐÔI DNA)</text>\n      <rect x=\"16\" y=\"34\" width=\"300\" height=\"54\" rx=\"8\" fill=\"#ecfdf5\" stroke=\"#10b981\"/>\n      <text x=\"166\" y=\"54\" font-size=\"9.5\" font-weight=\"800\" fill=\"#047857\">• Kì giữa II: Xếp 1 HÀNG trên mặt phẳng xích đạo</text>\n      <text x=\"166\" y=\"72\" font-size=\"9.5\" font-weight=\"700\" fill=\"#334155\">• Kì sau II: Tách 2 chromatid chị em về 2 cực</text>\n      <!-- 4 haploid cells -->\n      <circle cx=\"58\" cy=\"126\" r=\"22\" fill=\"#d1fae5\" stroke=\"#059669\" stroke-width=\"2\"/><text x=\"58\" y=\"130\" font-size=\"10\" font-weight=\"800\" fill=\"#065f46\">n đơn</text>\n      <circle cx=\"130\" cy=\"126\" r=\"22\" fill=\"#d1fae5\" stroke=\"#059669\" stroke-width=\"2\"/><text x=\"130\" y=\"130\" font-size=\"10\" font-weight=\"800\" fill=\"#065f46\">n đơn</text>\n      <circle cx=\"202\" cy=\"126\" r=\"22\" fill=\"#d1fae5\" stroke=\"#059669\" stroke-width=\"2\"/><text x=\"202\" y=\"130\" font-size=\"10\" font-weight=\"800\" fill=\"#065f46\">n đơn</text>\n      <circle cx=\"274\" cy=\"126\" r=\"22\" fill=\"#d1fae5\" stroke=\"#059669\" stroke-width=\"2\"/><text x=\"274\" y=\"130\" font-size=\"10\" font-weight=\"800\" fill=\"#065f46\">n đơn</text>\n    </g>\n    <!-- Bottom Summary -->\n    <rect x=\"20\" y=\"222\" width=\"720\" height=\"34\" rx=\"8\" fill=\"#f3e8ff\" stroke=\"#c084fc\"/>\n    <text x=\"380\" y=\"243\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"800\" fill=\"#6b21a8\">Kết quả: 1 tế bào mẹ (2n) → 4 tế bào con đơn bội (n) đa dạng di truyền • Phối hợp Thụ tinh (n × n = 2n) duy trì bộ NST loài</text>\n  </svg>",
  "18": "<svg viewBox=\"0 0 760 250\" class=\"w-full h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n    <rect width=\"760\" height=\"250\" rx=\"16\" fill=\"#fff1f2\" class=\"dark:fill-slate-900\"/>\n    <text x=\"380\" y=\"26\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"800\" fill=\"#be123c\">THỰC HÀNH: QUY TRÌNH LÀM TIÊU BẢN DẦM ÉP ĐỈNH RỄ HÀNH QUAN SÁT PHÂN BÀO</text>\n    <g transform=\"translate(20, 48)\" font-size=\"9.5\" text-anchor=\"middle\">\n      <rect x=\"0\" y=\"0\" width=\"165\" height=\"178\" rx=\"12\" fill=\"#ffffff\" stroke=\"#e11d48\" stroke-width=\"2\"/>\n      <circle cx=\"82\" cy=\"24\" r=\"13\" fill=\"#e11d48\"/><text x=\"82\" y=\"28\" font-size=\"11\" font-weight=\"800\" fill=\"#fff\">1</text>\n      <text x=\"82\" y=\"54\" font-size=\"10.5\" font-weight=\"800\" fill=\"#be123c\">CẮT &amp; CỐ ĐỊNH RỄ</text>\n      <text x=\"82\" y=\"80\" fill=\"#334155\">Cắt đầu rễ hành 5 mm</text>\n      <text x=\"82\" y=\"100\" fill=\"#334155\">Ngâm cố định trong</text>\n      <text x=\"82\" y=\"118\" font-weight=\"700\" fill=\"#be123c\">Dung dịch Carnoy (≥24h)</text>\n      <text x=\"82\" y=\"142\" font-size=\"8.5\" fill=\"#64748b\">Giữ nguyên trạng thái</text>\n      <text x=\"82\" y=\"156\" font-size=\"8.5\" fill=\"#64748b\">các kì phân bào</text>\n\n      <text x=\"176\" y=\"92\" font-size=\"16\" font-weight=\"900\" fill=\"#e11d48\">→</text>\n\n      <rect x=\"188\" y=\"0\" width=\"165\" height=\"178\" rx=\"12\" fill=\"#ffffff\" stroke=\"#e11d48\" stroke-width=\"2\"/>\n      <circle cx=\"270\" cy=\"24\" r=\"13\" fill=\"#e11d48\"/><text x=\"270\" y=\"28\" font-size=\"11\" font-weight=\"800\" fill=\"#fff\">2</text>\n      <text x=\"270\" y=\"54\" font-size=\"10.5\" font-weight=\"800\" fill=\"#be123c\">NHUỘM &amp; HƠ NÓNG</text>\n      <text x=\"270\" y=\"80\" fill=\"#334155\">Nhuộm thuốc nhuộm</text>\n      <text x=\"270\" y=\"100\" font-weight=\"800\" fill=\"#be123c\">Acetocarmine 2%</text>\n      <text x=\"270\" y=\"118\" fill=\"#334155\">Hơ ấm nhẹ 5–8 phút</text>\n      <text x=\"270\" y=\"142\" font-size=\"8.5\" font-weight=\"700\" fill=\"#dc2626\">(Tuyệt đối không đun sôi)</text>\n      <text x=\"270\" y=\"156\" font-size=\"8.5\" fill=\"#64748b\">NST bắt màu đỏ tím đậm</text>\n\n      <text x=\"364\" y=\"92\" font-size=\"16\" font-weight=\"900\" fill=\"#e11d48\">→</text>\n\n      <rect x=\"376\" y=\"0\" width=\"165\" height=\"178\" rx=\"12\" fill=\"#ffffff\" stroke=\"#e11d48\" stroke-width=\"2\"/>\n      <circle cx=\"458\" cy=\"24\" r=\"13\" fill=\"#e11d48\"/><text x=\"458\" y=\"28\" font-size=\"11\" font-weight=\"800\" fill=\"#fff\">3</text>\n      <text x=\"458\" y=\"54\" font-size=\"10.5\" font-weight=\"800\" fill=\"#be123c\">CẮT CHÓP &amp; DẦM ÉP</text>\n      <text x=\"458\" y=\"80\" fill=\"#334155\">Lấy đỉnh mô phân sinh</text>\n      <text x=\"458\" y=\"100\" font-weight=\"700\" fill=\"#be123c\">(~1,5 – 2 mm chóp rễ)</text>\n      <text x=\"458\" y=\"118\" fill=\"#334155\">Đậy lamen, ép thẳng nhẹ</text>\n      <text x=\"458\" y=\"142\" font-size=\"8.5\" fill=\"#64748b\">Dàn đều tế bào thành</text>\n      <text x=\"458\" y=\"156\" font-size=\"8.5\" fill=\"#64748b\">một lớp mỏng phẳng</text>\n\n      <text x=\"552\" y=\"92\" font-size=\"16\" font-weight=\"900\" fill=\"#e11d48\">→</text>\n\n      <rect x=\"564\" y=\"0\" width=\"156\" height=\"178\" rx=\"12\" fill=\"#ffffff\" stroke=\"#059669\" stroke-width=\"2\"/>\n      <circle cx=\"642\" cy=\"24\" r=\"13\" fill=\"#059669\"/><text x=\"642\" y=\"28\" font-size=\"11\" font-weight=\"800\" fill=\"#fff\">4</text>\n      <text x=\"642\" y=\"54\" font-size=\"10.5\" font-weight=\"800\" fill=\"#065f46\">QUAN SÁT 10× → 40×</text>\n      <text x=\"642\" y=\"80\" fill=\"#334155\">Tìm vùng phân chia 10×</text>\n      <text x=\"642\" y=\"100\" font-weight=\"700\" fill=\"#065f46\">Chuyển 40× nhận diện:</text>\n      <text x=\"642\" y=\"118\" fill=\"#334155\">Kì đầu, giữa, sau, cuối</text>\n      <text x=\"642\" y=\"142\" font-size=\"8.5\" fill=\"#64748b\">Vẽ hình &amp; chú thích NST</text>\n      <text x=\"642\" y=\"156\" font-size=\"8.5\" fill=\"#64748b\">trong báo cáo thực hành</text>\n    </g>\n  </svg>",
  "19": "<svg viewBox=\"0 0 760 275\" class=\"w-full h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n    <rect width=\"760\" height=\"275\" rx=\"16\" fill=\"#f0fdf4\" class=\"dark:fill-slate-900\"/>\n    <text x=\"380\" y=\"26\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"800\" fill=\"#065f46\">CÔNG NGHỆ TẾ BÀO THỰC VẬT (TÍNH TOÀN NĂNG) &amp; ĐỘNG VẬT (CHUYỂN NHÂN)</text>\n    <!-- Top Box: Plant Tissue Culture -->\n    <rect x=\"20\" y=\"42\" width=\"720\" height=\"104\" rx=\"12\" fill=\"#ffffff\" stroke=\"#16a34a\" stroke-width=\"2\"/>\n    <text x=\"380\" y=\"62\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"#15803d\">1. QUY TRÌNH NUÔI CẤY MÔ TẾ BÀO THỰC VẬT (DỰA TRÊN TÍNH TOÀN NĂNG CỦA TẾ BÀO)</text>\n    <g font-size=\"9.5\" font-weight=\"700\" text-anchor=\"middle\">\n      <rect x=\"35\" y=\"74\" width=\"125\" height=\"56\" rx=\"8\" fill=\"#dcfce7\" stroke=\"#16a34a\"/>\n      <text x=\"97\" y=\"95\" fill=\"#15803d\">Mẫu mô đỉnh chồi</text><text x=\"97\" y=\"114\" font-size=\"8.5\" fill=\"#334155\">Khử trùng sạch bệnh</text>\n      <text x=\"172\" y=\"105\" font-size=\"14\" fill=\"#16a34a\">→</text>\n      <rect x=\"184\" y=\"74\" width=\"135\" height=\"56\" rx=\"8\" fill=\"#dcfce7\" stroke=\"#16a34a\"/>\n      <text x=\"251\" y=\"95\" fill=\"#15803d\">Phản biệt hoá</text><text x=\"251\" y=\"114\" font-size=\"8.5\" fill=\"#334155\">Tạo Mô sẹo (Callus)</text>\n      <text x=\"331\" y=\"105\" font-size=\"14\" fill=\"#16a34a\">→</text>\n      <rect x=\"343\" y=\"74\" width=\"165\" height=\"56\" rx=\"8\" fill=\"#fef3c7\" stroke=\"#d97706\"/>\n      <text x=\"425\" y=\"95\" fill=\"#b45309\">Tái biệt hoá (Hormone)</text><text x=\"425\" y=\"114\" font-size=\"8.5\" fill=\"#334155\">Auxin / Cytokinin → Rễ &amp; Chồi</text>\n      <text x=\"520\" y=\"105\" font-size=\"14\" fill=\"#16a34a\">→</text>\n      <rect x=\"532\" y=\"74\" width=\"192\" height=\"56\" rx=\"8\" fill=\"#d1fae5\" stroke=\"#059669\" stroke-width=\"2\"/>\n      <text x=\"628\" y=\"95\" fill=\"#065f46\">Cây con hoàn chỉnh (In vitro)</text><text x=\"628\" y=\"114\" font-size=\"8.5\" fill=\"#047857\">Nhân nhanh, đồng nhất kiểu gene</text>\n    </g>\n\n    <!-- Bottom Box: Somatic Cell Nuclear Transfer (Dolly) -->\n    <rect x=\"20\" y=\"158\" width=\"720\" height=\"104\" rx=\"12\" fill=\"#ffffff\" stroke=\"#0284c7\" stroke-width=\"2\"/>\n    <text x=\"380\" y=\"178\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"#0369a1\">2. NHÂN BẢN VÔ TÍNH ĐỘNG VẬT BẰNG CHUYỂN NHÂN (CỪU DOLLY) &amp; TẾ BÀO GỐC</text>\n    <g font-size=\"9.5\" font-weight=\"700\" text-anchor=\"middle\">\n      <rect x=\"35\" y=\"190\" width=\"155\" height=\"56\" rx=\"8\" fill=\"#e0f2fe\" stroke=\"#0284c7\"/>\n      <text x=\"112\" y=\"210\" fill=\"#0369a1\">Nhân (2n) tuyến vú</text><text x=\"112\" y=\"228\" font-size=\"8.5\" fill=\"#334155\">Cừu mặt trắng (Cho nhân)</text>\n      <text x=\"202\" y=\"220\" font-size=\"14\" fill=\"#0284c7\">+</text>\n      <rect x=\"214\" y=\"190\" width=\"150\" height=\"56\" rx=\"8\" fill=\"#f1f5f9\" stroke=\"#64748b\"/>\n      <text x=\"289\" y=\"210\" fill=\"#334155\">Tế bào trứng bỏ nhân</text><text x=\"289\" y=\"228\" font-size=\"8.5\" fill=\"#64748b\">Cừu mặt đen (Cho TBC/Ti thể)</text>\n      <text x=\"376\" y=\"220\" font-size=\"14\" fill=\"#0284c7\">→</text>\n      <rect x=\"388\" y=\"190\" width=\"145\" height=\"56\" rx=\"8\" fill=\"#ede9fe\" stroke=\"#7c3aed\"/>\n      <text x=\"460\" y=\"210\" fill=\"#6d28d9\">Xung điện → Phôi sớm</text><text x=\"460\" y=\"228\" font-size=\"8.5\" fill=\"#334155\">Cấy vào tử cung mang thai hộ</text>\n      <text x=\"545\" y=\"220\" font-size=\"14\" fill=\"#0284c7\">→</text>\n      <rect x=\"557\" y=\"190\" width=\"167\" height=\"56\" rx=\"8\" fill=\"#fef3c7\" stroke=\"#d97706\" stroke-width=\"2\"/>\n      <text x=\"640\" y=\"210\" fill=\"#b45309\">Sinh ra Cừu Dolly</text><text x=\"640\" y=\"228\" font-size=\"8.5\" fill=\"#92400e\">Giống cừu cho nhân (Mặt trắng)</text>\n    </g>\n  </svg>",
  "20": "<svg viewBox=\"0 0 760 255\" class=\"w-full h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n    <rect width=\"760\" height=\"255\" rx=\"16\" fill=\"#f0fdfa\" class=\"dark:fill-slate-900\"/>\n    <text x=\"380\" y=\"26\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"800\" fill=\"#0f766e\">SỰ ĐA DẠNG VI SINH VẬT &amp; QUY TRÌNH PHÂN LẬP – NUÔI CẤY – ĐỊNH DANH</text>\n    <!-- 5 Step Flow -->\n    <g transform=\"translate(20, 48)\" font-size=\"9.5\" text-anchor=\"middle\">\n      <rect x=\"0\" y=\"0\" width=\"128\" height=\"145\" rx=\"10\" fill=\"#ffffff\" stroke=\"#0d9488\" stroke-width=\"2\"/>\n      <text x=\"64\" y=\"22\" font-weight=\"800\" fill=\"#0f766e\">1. THU MẪU TỰ NHIÊN</text>\n      <text x=\"64\" y=\"48\" fill=\"#334155\">Đất, nước, không khí,</text>\n      <text x=\"64\" y=\"65\" fill=\"#334155\">thực phẩm lên men</text>\n      <text x=\"64\" y=\"95\" font-size=\"8.5\" font-weight=\"700\" fill=\"#0d9488\">Chứa quần xã hỗn hợp</text>\n      <text x=\"64\" y=\"112\" font-size=\"8.5\" fill=\"#64748b\">nhiều loài VSV</text>\n\n      <text x=\"138\" y=\"76\" font-size=\"15\" font-weight=\"900\" fill=\"#0d9488\">→</text>\n\n      <rect x=\"148\" y=\"0\" width=\"136\" height=\"145\" rx=\"10\" fill=\"#ffffff\" stroke=\"#0d9488\" stroke-width=\"2\"/>\n      <text x=\"216\" y=\"22\" font-weight=\"800\" fill=\"#0f766e\">2. PHA LOÃNG / CẤY RIA</text>\n      <circle cx=\"216\" cy=\"68\" r=\"24\" fill=\"#fef3c7\" stroke=\"#d97706\" stroke-width=\"1.5\"/>\n      <path d=\"M 200 58 L 230 58 L 202 68 L 232 68 L 206 78 L 228 78\" fill=\"none\" stroke=\"#dc2626\" stroke-width=\"1.5\"/>\n      <text x=\"216\" y=\"110\" font-size=\"8.5\" font-weight=\"700\" fill=\"#b45309\">Trên môi trường thạch đặc</text>\n      <text x=\"216\" y=\"126\" font-size=\"8.5\" fill=\"#64748b\">(Đĩa Petri vô trùng)</text>\n\n      <text x=\"294\" y=\"76\" font-size=\"15\" font-weight=\"900\" fill=\"#0d9488\">→</text>\n\n      <rect x=\"304\" y=\"0\" width=\"132\" height=\"145\" rx=\"10\" fill=\"#ffffff\" stroke=\"#059669\" stroke-width=\"2\"/>\n      <text x=\"370\" y=\"22\" font-weight=\"800\" fill=\"#065f46\">3. Ủ ẤM &amp; KHUẨN LẠC</text>\n      <circle cx=\"370\" cy=\"68\" r=\"24\" fill=\"#ecfdf5\" stroke=\"#059669\" stroke-width=\"1.5\"/>\n      <circle cx=\"360\" cy=\"60\" r=\"3\" fill=\"#059669\"/><circle cx=\"378\" cy=\"64\" r=\"3\" fill=\"#dc2626\"/><circle cx=\"368\" cy=\"76\" r=\"3\" fill=\"#0284c7\"/>\n      <text x=\"370\" y=\"110\" font-size=\"8.5\" font-weight=\"700\" fill=\"#065f46\">1 tế bào → 1 Khuẩn lạc đơn</text>\n      <text x=\"370\" y=\"126\" font-size=\"8.5\" fill=\"#64748b\">Nhìn thấy bằng mắt thường</text>\n\n      <text x=\"446\" y=\"76\" font-size=\"15\" font-weight=\"900\" fill=\"#059669\">→</text>\n\n      <rect x=\"456\" y=\"0\" width=\"124\" height=\"145\" rx=\"10\" fill=\"#ffffff\" stroke=\"#0284c7\" stroke-width=\"2\"/>\n      <text x=\"518\" y=\"22\" font-weight=\"800\" fill=\"#0369a1\">4. PHÂN LẬP THUẦN</text>\n      <text x=\"518\" y=\"52\" fill=\"#334155\">Tách khuẩn lạc đơn</text>\n      <text x=\"518\" y=\"70\" fill=\"#334155\">sang môi trường mới</text>\n      <text x=\"518\" y=\"102\" font-size=\"8.5\" font-weight=\"700\" fill=\"#0284c7\">Thu chủng VSV thuần khiết</text>\n      <text x=\"518\" y=\"118\" font-size=\"8.5\" fill=\"#64748b\">(Không lẫn tạp)</text>\n\n      <text x=\"590\" y=\"76\" font-size=\"15\" font-weight=\"900\" fill=\"#0284c7\">→</text>\n\n      <rect x=\"600\" y=\"0\" width=\"120\" height=\"145\" rx=\"10\" fill=\"#ffffff\" stroke=\"#7c3aed\" stroke-width=\"2\"/>\n      <text x=\"660\" y=\"22\" font-weight=\"800\" fill=\"#6d28d9\">5. ĐỊNH DANH LOÀI</text>\n      <text x=\"660\" y=\"52\" fill=\"#334155\">• Quan sát hiển vi/Gram</text>\n      <text x=\"660\" y=\"70\" fill=\"#334155\">• Thử nghiệm hoá sinh</text>\n      <text x=\"660\" y=\"92\" font-size=\"8.5\" font-weight=\"700\" fill=\"#7c3aed\">• Giải trình tự DNA/RNA</text>\n      <text x=\"660\" y=\"112\" font-size=\"8.5\" fill=\"#64748b\">(Gene 16S rRNA)</text>\n    </g>\n    <!-- Bottom Groups -->\n    <rect x=\"20\" y=\"206\" width=\"720\" height=\"34\" rx=\"8\" fill=\"#ccfbf1\" stroke=\"#14b8a6\"/>\n    <text x=\"380\" y=\"227\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"800\" fill=\"#0f766e\">Các nhóm VSV: Nhân sơ (Vi khuẩn, Cổ khuẩn) • Nhân thực (Vi nấm: nấm men/nấm mốc, Vi tảo, Động vật nguyên sinh)</text>\n  </svg>",
  "21": "<svg viewBox=\"0 0 760 275\" class=\"w-full h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n    <rect width=\"760\" height=\"275\" rx=\"16\" fill=\"#f0fdf4\" class=\"dark:fill-slate-900\"/>\n    <text x=\"380\" y=\"26\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"800\" fill=\"#065f46\">ĐƯỜNG CONG SINH TRƯỞNG 4 PHA (NUÔI CẤY KHÔNG LIÊN TỤC) &amp; KIỂU DINH DƯỠNG VSV</text>\n    <!-- Left: Growth Curve -->\n    <rect x=\"20\" y=\"44\" width=\"445\" height=\"214\" rx=\"12\" fill=\"#ffffff\" stroke=\"#059669\" stroke-width=\"2\"/>\n    <text x=\"242\" y=\"64\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"#065f46\">1. ĐƯỜNG CONG SINH TRƯỞNG QUẦN THỂ VI KHUẨN (N_t = N_0 × 2^(t/g))</text>\n    <!-- Axes -->\n    <line x1=\"58\" y1=\"210\" x2=\"438\" y2=\"210\" stroke=\"#334155\" stroke-width=\"2\"/>\n    <line x1=\"58\" y1=\"210\" x2=\"58\" y2=\"80\" stroke=\"#334155\" stroke-width=\"2\"/>\n    <text x=\"48\" y=\"88\" text-anchor=\"end\" font-size=\"8.5\" font-weight=\"700\" fill=\"#334155\">log N</text>\n    <text x=\"435\" y=\"224\" text-anchor=\"end\" font-size=\"8.5\" font-weight=\"700\" fill=\"#334155\">Thời gian (t)</text>\n    <!-- Phase dividers -->\n    <line x1=\"135\" y1=\"82\" x2=\"135\" y2=\"210\" stroke=\"#cbd5e1\" stroke-dasharray=\"3 3\"/>\n    <line x1=\"235\" y1=\"82\" x2=\"235\" y2=\"210\" stroke=\"#cbd5e1\" stroke-dasharray=\"3 3\"/>\n    <line x1=\"345\" y1=\"82\" x2=\"345\" y2=\"210\" stroke=\"#cbd5e1\" stroke-dasharray=\"3 3\"/>\n    <!-- Curve: Lag -> Log -> Stationary -> Death -->\n    <path d=\"M 60 185 L 135 185 C 165 185, 200 100, 235 100 L 345 100 C 375 100, 410 175, 432 195\" fill=\"none\" stroke=\"#059669\" stroke-width=\"4\"/>\n    <!-- Phase Labels -->\n    <text x=\"96\" y=\"172\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"800\" fill=\"#0284c7\">1. Tiềm phát</text>\n    <text x=\"96\" y=\"200\" text-anchor=\"middle\" font-size=\"8\" fill=\"#64748b\">Thích nghi, N=N₀</text>\n    <text x=\"185\" y=\"130\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"800\" fill=\"#059669\">2. Luỹ thừa (Log)</text>\n    <text x=\"185\" y=\"200\" text-anchor=\"middle\" font-size=\"8\" fill=\"#059669\" font-weight=\"700\">Tăng cực nhanh</text>\n    <text x=\"290\" y=\"92\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"800\" fill=\"#d97706\">3. Cân bằng</text>\n    <text x=\"290\" y=\"200\" text-anchor=\"middle\" font-size=\"8\" fill=\"#b45309\">N cực đại (Sinh=Chết)</text>\n    <text x=\"390\" y=\"138\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"800\" fill=\"#dc2626\">4. Suy vong</text>\n    <text x=\"390\" y=\"200\" text-anchor=\"middle\" font-size=\"8\" fill=\"#dc2626\">Cạn chất, độc tăng</text>\n    <text x=\"242\" y=\"244\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"700\" fill=\"#0f766e\">• Nuôi cấy liên tục: Cấp dinh dưỡng &amp; lấy sản phẩm liên tục → Giữ ở pha luỹ thừa</text>\n\n    <!-- Right: 4 Nutritional Types & Reproduction -->\n    <rect x=\"480\" y=\"44\" width=\"260\" height=\"214\" rx=\"12\" fill=\"#ffffff\" stroke=\"#0284c7\" stroke-width=\"2\"/>\n    <text x=\"610\" y=\"64\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"#0369a1\">2. 4 KIỂU DINH DƯỠNG &amp; SINH SẢN</text>\n    <g font-size=\"9\" fill=\"#334155\">\n      <rect x=\"494\" y=\"74\" width=\"232\" height=\"32\" rx=\"6\" fill=\"#ecfdf5\"/>\n      <text x=\"610\" y=\"88\" text-anchor=\"middle\" font-weight=\"800\" fill=\"#047857\">Quang tự dưỡng (Ánh sáng + CO₂)</text>\n      <text x=\"610\" y=\"101\" text-anchor=\"middle\" font-size=\"8\">Vi khuẩn lam, Vi tảo, VK lưu huỳnh</text>\n\n      <rect x=\"494\" y=\"110\" width=\"232\" height=\"32\" rx=\"6\" fill=\"#f0f9ff\"/>\n      <text x=\"610\" y=\"124\" text-anchor=\"middle\" font-weight=\"800\" fill=\"#0369a1\">Quang dị dưỡng (Ánh sáng + Chất hữu cơ)</text>\n      <text x=\"610\" y=\"137\" text-anchor=\"middle\" font-size=\"8\">VK không chứa lưu huỳnh màu lục/tía</text>\n\n      <rect x=\"494\" y=\"146\" width=\"232\" height=\"32\" rx=\"6\" fill=\"#fef3c7\"/>\n      <text x=\"610\" y=\"160\" text-anchor=\"middle\" font-weight=\"800\" fill=\"#b45309\">Hoá tự dưỡng (Chất vô cơ + CO₂)</text>\n      <text x=\"610\" y=\"173\" text-anchor=\"middle\" font-size=\"8\">VK nitrat hoá, VK oxy hoá sắt/lưu huỳnh</text>\n\n      <rect x=\"494\" y=\"182\" width=\"232\" height=\"32\" rx=\"6\" fill=\"#ffe4e6\"/>\n      <text x=\"610\" y=\"196\" text-anchor=\"middle\" font-weight=\"800\" fill=\"#be123c\">Hoá dị dưỡng (Chất hữu cơ + Chất hữu cơ)</text>\n      <text x=\"610\" y=\"209\" text-anchor=\"middle\" font-size=\"8\">Nấm, Động vật nguyên sinh, đa số VK</text>\n    </g>\n    <text x=\"610\" y=\"232\" text-anchor=\"middle\" font-size=\"8.5\" font-weight=\"700\" fill=\"#334155\">Sinh sản: Phân đôi • Nảy chồi • Bào tử</text>\n    <text x=\"610\" y=\"246\" text-anchor=\"middle\" font-size=\"8\" fill=\"#dc2626\" font-weight=\"700\">(Nội bào tử VK chỉ là dạng bảo vệ, không phải sinh sản)</text>\n  </svg>",
  "22": "<svg viewBox=\"0 0 760 265\" class=\"w-full h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n    <rect width=\"760\" height=\"265\" rx=\"16\" fill=\"#f0fdf4\" class=\"dark:fill-slate-900\"/>\n    <text x=\"380\" y=\"26\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"800\" fill=\"#065f46\">VAI TRÒ TUẦN HOÀN VẬT CHẤT &amp; 4 TRỤ CỘT ỨNG DỤNG CÔNG NGHỆ VI SINH VẬT</text>\n    <!-- 4 Pillars -->\n    <g transform=\"translate(20, 44)\" font-size=\"9.5\" text-anchor=\"middle\">\n      <rect x=\"0\" y=\"0\" width=\"170\" height=\"156\" rx=\"12\" fill=\"#ffffff\" stroke=\"#d97706\" stroke-width=\"2\"/>\n      <rect x=\"0\" y=\"0\" width=\"170\" height=\"30\" rx=\"10\" fill=\"#fef3c7\"/>\n      <text x=\"85\" y=\"20\" font-size=\"10.5\" font-weight=\"800\" fill=\"#b45309\">1. THỰC PHẨM LÊN MEN</text>\n      <text x=\"85\" y=\"50\" fill=\"#334155\">• VK Lactic: Sữa chua,</text>\n      <text x=\"85\" y=\"66\" fill=\"#334155\">phô mai, dưa cải muối</text>\n      <text x=\"85\" y=\"88\" fill=\"#334155\">• Nấm men: Rượu, bia,</text>\n      <text x=\"85\" y=\"104\" fill=\"#334155\">làm nở bột bánh mì</text>\n      <text x=\"85\" y=\"126\" font-weight=\"700\" fill=\"#b45309\">• Nấm mốc: Nước tương,</text>\n      <text x=\"85\" y=\"142\" font-weight=\"700\" fill=\"#b45309\">enzyme thuỷ phân đạm</text>\n\n      <rect x=\"183\" y=\"0\" width=\"170\" height=\"156\" rx=\"12\" fill=\"#ffffff\" stroke=\"#e11d48\" stroke-width=\"2\"/>\n      <rect x=\"183\" y=\"0\" width=\"170\" height=\"30\" rx=\"10\" fill=\"#ffe4e6\"/>\n      <text x=\"268\" y=\"20\" font-size=\"10.5\" font-weight=\"800\" fill=\"#be123c\">2. Y HỌC &amp; DƯỢC PHẨM</text>\n      <text x=\"268\" y=\"50\" fill=\"#334155\">• Xạ khuẩn / Nấm mốc:</text>\n      <text x=\"268\" y=\"66\" font-weight=\"700\" fill=\"#be123c\">Sản xuất Kháng sinh</text>\n      <text x=\"268\" y=\"88\" fill=\"#334155\">• E. coli tái tổ hợp:</text>\n      <text x=\"268\" y=\"104\" font-weight=\"700\" fill=\"#0284c7\">Hormone Insulin, Vaccine</text>\n      <text x=\"268\" y=\"126\" fill=\"#334155\">• Men vi sinh Probiotics</text>\n      <text x=\"268\" y=\"142\" fill=\"#334155\">cân bằng hệ đường ruột</text>\n\n      <rect x=\"366\" y=\"0\" width=\"170\" height=\"156\" rx=\"12\" fill=\"#ffffff\" stroke=\"#16a34a\" stroke-width=\"2\"/>\n      <rect x=\"366\" y=\"0\" width=\"170\" height=\"30\" rx=\"10\" fill=\"#dcfce7\"/>\n      <text x=\"451\" y=\"20\" font-size=\"10.5\" font-weight=\"800\" fill=\"#15803d\">3. NÔNG NGHIỆP XANH</text>\n      <text x=\"451\" y=\"50\" fill=\"#334155\">• Phân vi sinh cố định đạm</text>\n      <text x=\"451\" y=\"66\" font-weight=\"700\" fill=\"#15803d\">(Rhizobium nốt sần đậu)</text>\n      <text x=\"451\" y=\"88\" fill=\"#334155\">• Phân vi sinh phân giải lân</text>\n      <text x=\"451\" y=\"104\" fill=\"#334155\">&amp; phân giải cellulose</text>\n      <text x=\"451\" y=\"126\" font-weight=\"700\" fill=\"#047857\">• Thuốc trừ sâu sinh học Bt</text>\n      <text x=\"451\" y=\"142\" fill=\"#334155\">Ủ chua thức ăn chăn nuôi</text>\n\n      <rect x=\"549\" y=\"0\" width=\"171\" height=\"156\" rx=\"12\" fill=\"#ffffff\" stroke=\"#0284c7\" stroke-width=\"2\"/>\n      <rect x=\"549\" y=\"0\" width=\"171\" height=\"30\" rx=\"10\" fill=\"#e0f2fe\"/>\n      <text x=\"634\" y=\"20\" font-size=\"10.5\" font-weight=\"800\" fill=\"#0369a1\">4. CÔNG NGHIỆP &amp; MÔI TRƯỜNG</text>\n      <text x=\"634\" y=\"50\" fill=\"#334155\">• Xử lí nước thải hiếu khí /</text>\n      <text x=\"634\" y=\"66\" font-weight=\"700\" fill=\"#0369a1\">kị khí tạo khí Biogas (CH₄)</text>\n      <text x=\"634\" y=\"88\" fill=\"#334155\">• Phân huỷ rác hữu cơ,</text>\n      <text x=\"634\" y=\"104\" fill=\"#334155\">xử lí vết dầu tràn biển</text>\n      <text x=\"634\" y=\"126\" font-weight=\"700\" fill=\"#0f766e\">• Sản xuất acid hữu cơ,</text>\n      <text x=\"634\" y=\"142\" font-weight=\"700\" fill=\"#0f766e\">nhiên liệu sinh học Ethanol</text>\n    </g>\n    <!-- Bottom Cycle Bar -->\n    <rect x=\"20\" y=\"212\" width=\"720\" height=\"36\" rx=\"10\" fill=\"#d1fae5\" stroke=\"#10b981\" stroke-width=\"1.5\"/>\n    <text x=\"380\" y=\"234\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"800\" fill=\"#065f46\">♻️ Vai trò sinh thái tự nhiên: VSV phân giải xác hữu cơ → Chất khoáng vô cơ (CO₂, NH₄⁺, NO₃⁻) khép kín tuần hoàn vật chất</text>\n  </svg>",
  "23": "<svg viewBox=\"0 0 760 250\" class=\"w-full h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n    <rect width=\"760\" height=\"250\" rx=\"16\" fill=\"#fffbeb\" class=\"dark:fill-slate-900\"/>\n    <text x=\"380\" y=\"26\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"800\" fill=\"#b45309\">THỰC HÀNH: QUY TRÌNH LÊN MEN LACTIC LÀM SỮA CHUA &amp; MUỐI CHUA RAU CỦ</text>\n    <g transform=\"translate(20, 46)\" font-size=\"9.5\" text-anchor=\"middle\">\n      <rect x=\"0\" y=\"0\" width=\"165\" height=\"182\" rx=\"12\" fill=\"#ffffff\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n      <circle cx=\"82\" cy=\"24\" r=\"13\" fill=\"#f59e0b\"/><text x=\"82\" y=\"28\" font-size=\"11\" font-weight=\"800\" fill=\"#fff\">1</text>\n      <text x=\"82\" y=\"54\" font-size=\"10.5\" font-weight=\"800\" fill=\"#b45309\">PHA SỮA (40–45°C)</text>\n      <text x=\"82\" y=\"80\" fill=\"#334155\">Pha sữa tươi / sữa đặc</text>\n      <text x=\"82\" y=\"98\" fill=\"#334155\">với nước đun sôi để ấm</text>\n      <text x=\"82\" y=\"120\" font-weight=\"800\" fill=\"#dc2626\">Nhiệt độ: 40 – 45°C</text>\n      <text x=\"82\" y=\"142\" font-size=\"8.5\" fill=\"#64748b\">(Nếu quá nóng &gt;60°C sẽ</text>\n      <text x=\"82\" y=\"156\" font-size=\"8.5\" fill=\"#64748b\">giết chết vi khuẩn giống)</text>\n\n      <text x=\"176\" y=\"94\" font-size=\"16\" font-weight=\"900\" fill=\"#d97706\">→</text>\n\n      <rect x=\"188\" y=\"0\" width=\"165\" height=\"182\" rx=\"12\" fill=\"#ffffff\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n      <circle cx=\"270\" cy=\"24\" r=\"13\" fill=\"#f59e0b\"/><text x=\"270\" y=\"28\" font-size=\"11\" font-weight=\"800\" fill=\"#fff\">2</text>\n      <text x=\"270\" y=\"54\" font-size=\"10.5\" font-weight=\"800\" fill=\"#b45309\">CẤY MEN CÁI (STARTER)</text>\n      <text x=\"270\" y=\"80\" fill=\"#334155\">Bổ sung sữa chua cái</text>\n      <text x=\"270\" y=\"98\" font-weight=\"700\" fill=\"#059669\">(Chứa VK Lactobacillus)</text>\n      <text x=\"270\" y=\"120\" fill=\"#334155\">Khuấy nhẹ đều tay,</text>\n      <text x=\"270\" y=\"142\" font-size=\"8.5\" fill=\"#64748b\">rót vào hũ tiệt trùng</text>\n      <text x=\"270\" y=\"156\" font-size=\"8.5\" fill=\"#64748b\">&amp; đậy kín nắp (kị khí)</text>\n\n      <text x=\"364\" y=\"94\" font-size=\"16\" font-weight=\"900\" fill=\"#d97706\">→</text>\n\n      <rect x=\"376\" y=\"0\" width=\"165\" height=\"182\" rx=\"12\" fill=\"#ffffff\" stroke=\"#059669\" stroke-width=\"2\"/>\n      <circle cx=\"458\" cy=\"24\" r=\"13\" fill=\"#059669\"/><text x=\"458\" y=\"28\" font-size=\"11\" font-weight=\"800\" fill=\"#fff\">3</text>\n      <text x=\"458\" y=\"54\" font-size=\"10.5\" font-weight=\"800\" fill=\"#065f46\">Ủ ẤM 40–45°C (6–8h)</text>\n      <text x=\"458\" y=\"80\" font-weight=\"700\" fill=\"#047857\">Lactose → Lactic acid</text>\n      <text x=\"458\" y=\"98\" fill=\"#334155\">Hạ pH xuống ~ 4,5</text>\n      <text x=\"458\" y=\"120\" font-weight=\"800\" fill=\"#b45309\">Protein Casein kết tủa</text>\n      <text x=\"458\" y=\"142\" font-size=\"8.5\" fill=\"#64748b\">Sữa chuyển trạng thái</text>\n      <text x=\"458\" y=\"156\" font-size=\"8.5\" fill=\"#64748b\">đông tụ sánh mịn, chua dịu</text>\n\n      <text x=\"552\" y=\"94\" font-size=\"16\" font-weight=\"900\" fill=\"#059669\">→</text>\n\n      <rect x=\"564\" y=\"0\" width=\"156\" height=\"182\" rx=\"12\" fill=\"#ffffff\" stroke=\"#0284c7\" stroke-width=\"2\"/>\n      <circle cx=\"642\" cy=\"24\" r=\"13\" fill=\"#0284c7\"/><text x=\"642\" y=\"28\" font-size=\"11\" font-weight=\"800\" fill=\"#fff\">4</text>\n      <text x=\"642\" y=\"54\" font-size=\"10.5\" font-weight=\"800\" fill=\"#0369a1\">BẢO QUẢN LẠNH (4–6°C)</text>\n      <text x=\"642\" y=\"80\" fill=\"#334155\">Đưa vào ngăn mát</text>\n      <text x=\"642\" y=\"98\" fill=\"#334155\">tủ lạnh ngay khi đạt</text>\n      <text x=\"642\" y=\"120\" font-weight=\"700\" fill=\"#0284c7\">Ức chế VK tiếp tục lên men</text>\n      <text x=\"642\" y=\"142\" font-size=\"8.5\" fill=\"#64748b\">Giữ hương vị thơm ngon,</text>\n      <text x=\"642\" y=\"156\" font-size=\"8.5\" fill=\"#64748b\">không bị quá chua/tách nước</text>\n    </g>\n  </svg>",
  "24": "<svg viewBox=\"0 0 760 275\" class=\"w-full h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n    <rect width=\"760\" height=\"275\" rx=\"16\" fill=\"#fff1f2\" class=\"dark:fill-slate-900\"/>\n    <text x=\"380\" y=\"26\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"800\" fill=\"#be123c\">CẤU TẠO HẠT VIRUS (VIRION) &amp; 5 GIAI ĐOẠN CHU TRÌNH NHÂN LÊN TRONG TẾ BÀO CHỦ</text>\n    <!-- Top Box: Virion Structure -->\n    <rect x=\"20\" y=\"42\" width=\"720\" height=\"84\" rx=\"12\" fill=\"#ffffff\" stroke=\"#e11d48\" stroke-width=\"2\"/>\n    <text x=\"155\" y=\"64\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"#be123c\">CẤU TẠO HẠT VIRUS (PHI TẾ BÀO)</text>\n    <circle cx=\"58\" cy=\"88\" r=\"24\" fill=\"#ffe4e6\" stroke=\"#e11d48\" stroke-width=\"2.5\"/>\n    <polygon points=\"58,70 74,80 74,96 58,106 42,96 42,80\" fill=\"#fecdd3\" stroke=\"#be123c\" stroke-width=\"1.5\"/>\n    <path d=\"M 50 88 Q 58 78, 66 88\" fill=\"none\" stroke=\"#7c3aed\" stroke-width=\"2.5\"/>\n    <text x=\"195\" y=\"86\" font-size=\"9.5\" fill=\"#334155\">• <tspan font-weight=\"800\" fill=\"#7c3aed\">Lõi Nucleic acid:</tspan> DNA hoặc RNA (1 hoặc 2 mạch)</text>\n    <text x=\"195\" y=\"106\" font-size=\"9.5\" fill=\"#334155\">• <tspan font-weight=\"800\" fill=\"#be123c\">Vỏ Capsid:</tspan> Cấu tạo từ các đơn vị protein Capsomere</text>\n    <text x=\"485\" y=\"86\" font-size=\"9.5\" fill=\"#334155\">• <tspan font-weight=\"800\" fill=\"#0369a1\">Màng bọc (Envelope):</tspan> Lớp lipid kép + <tspan font-weight=\"700\">Gai Glycoprotein</tspan></text>\n    <text x=\"485\" y=\"106\" font-size=\"9.5\" fill=\"#334155\">• <tspan font-weight=\"800\" fill=\"#059669\">3 Dạng hình thái:</tspan> Xoắn (TMV) • Khối đa diện (HIV) • Hỗn hợp (Phage)</text>\n\n    <!-- Bottom: 5 Stages of Viral Replication -->\n    <g transform=\"translate(20, 138)\" font-size=\"9.5\" text-anchor=\"middle\">\n      <rect x=\"0\" y=\"0\" width=\"130\" height=\"120\" rx=\"10\" fill=\"#ffffff\" stroke=\"#e11d48\" stroke-width=\"2\"/>\n      <circle cx=\"65\" cy=\"20\" r=\"11\" fill=\"#e11d48\"/><text x=\"65\" y=\"24\" font-size=\"10\" font-weight=\"800\" fill=\"#fff\">1</text>\n      <text x=\"65\" y=\"45\" font-weight=\"800\" fill=\"#be123c\">HẤP PHỤ (BÁM)</text>\n      <text x=\"65\" y=\"66\" font-size=\"8.5\" fill=\"#334155\">Gai glycoprotein / lông đuôi</text>\n      <text x=\"65\" y=\"82\" font-size=\"8.5\" font-weight=\"700\" fill=\"#be123c\">gắn đặc hiệu Thụ thể</text>\n      <text x=\"65\" y=\"98\" font-size=\"8.5\" fill=\"#64748b\">bề mặt tế bào vật chủ</text>\n\n      <text x=\"139\" y=\"64\" font-size=\"14\" font-weight=\"900\" fill=\"#e11d48\">→</text>\n\n      <rect x=\"148\" y=\"0\" width=\"130\" height=\"120\" rx=\"10\" fill=\"#ffffff\" stroke=\"#e11d48\" stroke-width=\"2\"/>\n      <circle cx=\"213\" cy=\"20\" r=\"11\" fill=\"#e11d48\"/><text x=\"213\" y=\"24\" font-size=\"10\" font-weight=\"800\" fill=\"#fff\">2</text>\n      <text x=\"213\" y=\"45\" font-weight=\"800\" fill=\"#be123c\">XÂM NHẬP</text>\n      <text x=\"213\" y=\"66\" font-size=\"8.5\" fill=\"#334155\">• Phage: Bơm lõi DNA vào</text>\n      <text x=\"213\" y=\"82\" font-size=\"8.5\" fill=\"#334155\">• Virus ĐV: Nhập bào /</text>\n      <text x=\"213\" y=\"98\" font-size=\"8.5\" font-weight=\"700\" fill=\"#be123c\">Dung hợp màng &amp; Cởi vỏ</text>\n\n      <text x=\"287\" y=\"64\" font-size=\"14\" font-weight=\"900\" fill=\"#e11d48\">→</text>\n\n      <rect x=\"296\" y=\"0\" width=\"130\" height=\"120\" rx=\"10\" fill=\"#ffffff\" stroke=\"#7c3aed\" stroke-width=\"2\"/>\n      <circle cx=\"361\" cy=\"20\" r=\"11\" fill=\"#7c3aed\"/><text x=\"361\" y=\"24\" font-size=\"10\" font-weight=\"800\" fill=\"#fff\">3</text>\n      <text x=\"361\" y=\"45\" font-weight=\"800\" fill=\"#6d28d9\">SINH TỔNG HỢP</text>\n      <text x=\"361\" y=\"66\" font-size=\"8.5\" fill=\"#334155\">Dùng enzyme, ribosome,</text>\n      <text x=\"361\" y=\"82\" font-size=\"8.5\" fill=\"#334155\">nguyên liệu tế bào chủ</text>\n      <text x=\"361\" y=\"98\" font-size=\"8.5\" font-weight=\"700\" fill=\"#6d28d9\">tổng hợp DNA/RNA + Vỏ</text>\n\n      <text x=\"435\" y=\"64\" font-size=\"14\" font-weight=\"900\" fill=\"#7c3aed\">→</text>\n\n      <rect x=\"444\" y=\"0\" width=\"126\" height=\"120\" rx=\"10\" fill=\"#ffffff\" stroke=\"#0284c7\" stroke-width=\"2\"/>\n      <circle cx=\"507\" cy=\"20\" r=\"11\" fill=\"#0284c7\"/><text x=\"507\" y=\"24\" font-size=\"10\" font-weight=\"800\" fill=\"#fff\">4</text>\n      <text x=\"507\" y=\"45\" font-weight=\"800\" fill=\"#0369a1\">LẮP RÁP</text>\n      <text x=\"507\" y=\"66\" font-size=\"8.5\" fill=\"#334155\">Lắp lõi nucleic acid</text>\n      <text x=\"507\" y=\"82\" font-size=\"8.5\" fill=\"#334155\">vào trong vỏ Capsid</text>\n      <text x=\"507\" y=\"98\" font-size=\"8.5\" font-weight=\"700\" fill=\"#0369a1\">tạo hạt Virion hoàn chỉnh</text>\n\n      <text x=\"579\" y=\"64\" font-size=\"14\" font-weight=\"900\" fill=\"#0284c7\">→</text>\n\n      <rect x=\"588\" y=\"0\" width=\"132\" height=\"120\" rx=\"10\" fill=\"#ffffff\" stroke=\"#059669\" stroke-width=\"2\"/>\n      <circle cx=\"654\" cy=\"20\" r=\"11\" fill=\"#059669\"/><text x=\"654\" y=\"24\" font-size=\"10\" font-weight=\"800\" fill=\"#fff\">5</text>\n      <text x=\"654\" y=\"45\" font-weight=\"800\" fill=\"#065f46\">GIẢI PHÓNG</text>\n      <text x=\"654\" y=\"66\" font-size=\"8.5\" font-weight=\"700\" fill=\"#dc2626\">• Chu trình tan (Phá vỡ TB)</text>\n      <text x=\"654\" y=\"82\" font-size=\"8.5\" font-weight=\"700\" fill=\"#059669\">• Nảy chồi / Tiềm tan</text>\n      <text x=\"654\" y=\"98\" font-size=\"8.5\" fill=\"#64748b\">(Cài hệ gene vào NST chủ)</text>\n    </g>\n  </svg>",
  "25": "<svg viewBox=\"0 0 760 270\" class=\"w-full h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n    <rect width=\"760\" height=\"270\" rx=\"16\" fill=\"#f0fdf4\" class=\"dark:fill-slate-900\"/>\n    <text x=\"380\" y=\"26\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"800\" fill=\"#065f46\">PHƯƠNG THỨC LÂY TRUYỀN VIRUS, PHÒNG BỆNH &amp; THÀNH TỰU ỨNG DỤNG VIRUS</text>\n    <!-- Left Box: Transmission & Diseases -->\n    <rect x=\"20\" y=\"44\" width=\"352\" height=\"208\" rx=\"12\" fill=\"#ffffff\" stroke=\"#e11d48\" stroke-width=\"2\"/>\n    <text x=\"196\" y=\"64\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"#be123c\">1. ĐƯỜNG LÂY TRUYỀN &amp; BỆNH DO VIRUS / PRION</text>\n    <rect x=\"34\" y=\"76\" width=\"324\" height=\"52\" rx=\"8\" fill=\"#fff1f2\"/>\n    <text x=\"196\" y=\"94\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"800\" fill=\"#be123c\">Lây ngang: Hô hấp (Cúm, SARS-CoV-2) • Tiêu hoá (Rotavirus)</text>\n    <text x=\"196\" y=\"110\" text-anchor=\"middle\" font-size=\"9\" fill=\"#334155\">Máu / Tình dục (HIV, HBV) • Vector côn trùng (Sốt xuất huyết) • Lây dọc: Mẹ → Con</text>\n\n    <rect x=\"34\" y=\"136\" width=\"324\" height=\"54\" rx=\"8\" fill=\"#fef3c7\"/>\n    <text x=\"196\" y=\"154\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"800\" fill=\"#b45309\">HIV tấn công bạch cầu T-CD4 → Suy giảm miễn dịch (AIDS)</text>\n    <text x=\"196\" y=\"170\" text-anchor=\"middle\" font-size=\"9\" fill=\"#334155\">Thực vật: Xâm nhập qua vết thương côn trùng chích hút &amp; truyền qua cầu sinh chất</text>\n    <text x=\"196\" y=\"206\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"800\" fill=\"#7c3aed\">⚠️ Prion: Phân tử Protein sai cấu hình (Không có DNA/RNA) gây bệnh bò điên</text>\n    <text x=\"196\" y=\"224\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"700\" fill=\"#059669\">Phòng bệnh: Tiêm Vaccine chủ động • Thuốc kháng virus ARV (Kháng sinh vô hiệu)</text>\n\n    <!-- Right Box: 3 Applications of Viruses -->\n    <rect x=\"388\" y=\"44\" width=\"352\" height=\"208\" rx=\"12\" fill=\"#ffffff\" stroke=\"#059669\" stroke-width=\"2\"/>\n    <text x=\"564\" y=\"64\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"#065f46\">2. BA THÀNH TỰU ỨNG DỤNG VIRUS TRONG KHOA HỌC</text>\n    <rect x=\"404\" y=\"76\" width=\"320\" height=\"50\" rx=\"8\" fill=\"#ecfdf5\" stroke=\"#10b981\"/>\n    <text x=\"564\" y=\"94\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"800\" fill=\"#047857\">① Sản xuất Vaccine &amp; Chế phẩm sinh học (Interferon)</text>\n    <text x=\"564\" y=\"112\" text-anchor=\"middle\" font-size=\"9\" fill=\"#334155\">Vaccine bất hoạt, giảm độc lực, vector virus hoặc mRNA tạo miễn dịch đặc hiệu</text>\n\n    <rect x=\"404\" y=\"134\" width=\"320\" height=\"50\" rx=\"8\" fill=\"#f0f9ff\" stroke=\"#0284c7\"/>\n    <text x=\"564\" y=\"152\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"800\" fill=\"#0369a1\">② Làm Vector (Thể truyền) chuyển gene trong Công nghệ di truyền</text>\n    <text x=\"564\" y=\"170\" text-anchor=\"middle\" font-size=\"9\" fill=\"#334155\">Cắt bỏ gene độc của virus, gắn gene lành/gene đích đưa vào tế bào vật chủ</text>\n\n    <rect x=\"404\" y=\"192\" width=\"320\" height=\"50\" rx=\"8\" fill=\"#fef3c7\" stroke=\"#d97706\"/>\n    <text x=\"564\" y=\"210\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"800\" fill=\"#b45309\">③ Sản xuất Thuốc trừ sâu sinh học từ Virus (Chế phẩm NPV)</text>\n    <text x=\"564\" y=\"228\" text-anchor=\"middle\" font-size=\"9\" fill=\"#334155\">Diệt đặc hiệu sâu hại cây trồng mà không gây ô nhiễm môi trường &amp; thiên địch</text>\n  </svg>",
  "26": "<svg viewBox=\"0 0 760 250\" class=\"w-full h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n    <rect width=\"760\" height=\"250\" rx=\"16\" fill=\"#f0fdfa\" class=\"dark:fill-slate-900\"/>\n    <text x=\"380\" y=\"26\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"800\" fill=\"#0f766e\">THỰC HÀNH DỰ ÁN: ĐIỀU TRA BỆNH DO VIRUS &amp; TRUYỀN THÔNG Y TẾ CỘNG ĐỒNG</text>\n    <g transform=\"translate(20, 48)\" font-size=\"9.5\" text-anchor=\"middle\">\n      <rect x=\"0\" y=\"0\" width=\"168\" height=\"178\" rx=\"12\" fill=\"#ffffff\" stroke=\"#0d9488\" stroke-width=\"2\"/>\n      <circle cx=\"84\" cy=\"24\" r=\"13\" fill=\"#0d9488\"/><text x=\"84\" y=\"28\" font-size=\"11\" font-weight=\"800\" fill=\"#fff\">1</text>\n      <text x=\"84\" y=\"54\" font-size=\"10.5\" font-weight=\"800\" fill=\"#0f766e\">CHỌN CHỦ ĐỀ DUYỆT</text>\n      <text x=\"84\" y=\"80\" fill=\"#334155\">• Bệnh ở người: Cúm,</text>\n      <text x=\"84\" y=\"96\" fill=\"#334155\">Sốt xuất huyết, HIV, Dại</text>\n      <text x=\"84\" y=\"116\" fill=\"#334155\">• Cây trồng: Khảm lá,</text>\n      <text x=\"84\" y=\"132\" fill=\"#334155\">Vàng lùn xoắn lá lúa</text>\n      <text x=\"84\" y=\"156\" font-size=\"8.5\" font-weight=\"700\" fill=\"#0d9488\">Lập phiếu điều tra chuẩn</text>\n\n      <text x=\"178\" y=\"92\" font-size=\"16\" font-weight=\"900\" fill=\"#0d9488\">→</text>\n\n      <rect x=\"190\" y=\"0\" width=\"168\" height=\"178\" rx=\"12\" fill=\"#ffffff\" stroke=\"#0284c7\" stroke-width=\"2\"/>\n      <circle cx=\"274\" cy=\"24\" r=\"13\" fill=\"#0284c7\"/><text x=\"274\" y=\"28\" font-size=\"11\" font-weight=\"800\" fill=\"#fff\">2</text>\n      <text x=\"274\" y=\"54\" font-size=\"10.5\" font-weight=\"800\" fill=\"#0369a1\">THU THẬP &amp; KIỂM CHỨNG</text>\n      <text x=\"274\" y=\"80\" fill=\"#334155\">Nguồn Bộ Y tế, WHO,</text>\n      <text x=\"274\" y=\"96\" fill=\"#334155\">Trạm Bảo vệ thực vật</text>\n      <text x=\"274\" y=\"118\" font-weight=\"700\" fill=\"#0369a1\">Tác nhân • Đường lây</text>\n      <text x=\"274\" y=\"134\" font-weight=\"700\" fill=\"#0369a1\">Triệu chứng • Cách phòng</text>\n      <text x=\"274\" y=\"156\" font-size=\"8.5\" fill=\"#dc2626\">Không tự lấy mẫu bệnh phẩm</text>\n\n      <text x=\"368\" y=\"92\" font-size=\"16\" font-weight=\"900\" fill=\"#0284c7\">→</text>\n\n      <rect x=\"380\" y=\"0\" width=\"168\" height=\"178\" rx=\"12\" fill=\"#ffffff\" stroke=\"#059669\" stroke-width=\"2\"/>\n      <circle cx=\"464\" cy=\"24\" r=\"13\" fill=\"#059669\"/><text x=\"464\" y=\"28\" font-size=\"11\" font-weight=\"800\" fill=\"#fff\">3</text>\n      <text x=\"464\" y=\"54\" font-size=\"10.5\" font-weight=\"800\" fill=\"#065f46\">XỬ LÍ &amp; PHÂN TÍCH</text>\n      <text x=\"464\" y=\"80\" fill=\"#334155\">Phân biệt dữ liệu thực tế</text>\n      <text x=\"464\" y=\"96\" fill=\"#334155\">với ý kiến chủ quan</text>\n      <text x=\"464\" y=\"118\" font-weight=\"700\" fill=\"#065f46\">Phân biệt triệu chứng virus</text>\n      <text x=\"464\" y=\"134\" fill=\"#334155\">với nấm/vi khuẩn/thiếu khoáng</text>\n      <text x=\"464\" y=\"156\" font-size=\"8.5\" fill=\"#64748b\">Bảo mật thông tin cá nhân</text>\n\n      <text x=\"558\" y=\"92\" font-size=\"16\" font-weight=\"900\" fill=\"#059669\">→</text>\n\n      <rect x=\"570\" y=\"0\" width=\"150\" height=\"178\" rx=\"12\" fill=\"#ffffff\" stroke=\"#d97706\" stroke-width=\"2\"/>\n      <circle cx=\"645\" cy=\"24\" r=\"13\" fill=\"#d97706\"/><text x=\"645\" y=\"28\" font-size=\"11\" font-weight=\"800\" fill=\"#fff\">4</text>\n      <text x=\"645\" y=\"54\" font-size=\"10.5\" font-weight=\"800\" fill=\"#b45309\">TUYÊN TRUYỀN</text>\n      <text x=\"645\" y=\"80\" font-weight=\"700\" fill=\"#b45309\">Thiết kế Poster / Tờ rơi</text>\n      <text x=\"645\" y=\"98\" fill=\"#334155\">Ngắn gọn, dễ hiểu</text>\n      <text x=\"645\" y=\"118\" font-weight=\"700\" fill=\"#059669\">Nêu rõ hành động phòng</text>\n      <text x=\"645\" y=\"134\" fill=\"#334155\">&amp; nơi hỗ trợ y tế</text>\n      <text x=\"645\" y=\"156\" font-size=\"8.5\" font-weight=\"700\" fill=\"#be123c\">Không gây hoang mang/kì thị</text>\n    </g>\n  </svg>"
};
module.exports = diagrams;
